    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect next-item match gets big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item can still fit here: mild reward proportional to closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item: penalize.
        score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 10.0;
    }

    // Prefer bins that deviate from mean residual (tight bins get priority).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate harder.
