pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, with a smooth convex penalty
    let mut score = post + (post / cap) * (post / cap) * 20.0;

    // Smooth non-linear coupling with stream progress: tighten packing as stream advances
    score *= 1.0 + 0.8 * progress * (1.0 - progress) * (post / cap);

    // Lookahead synergy: reward when next item exactly or nearly fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > post_residual {
        // Dead space risk: next item cannot use leftover space
        score += (next_item_size as f64 / cap) * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening new bins unless residual is very tight,
    // with penalty decaying smoothly as mean residual of open bins grows
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (post / cap);
        let crowd = (open_bins_count as f64).ln().max(1.0);
        score += 25.0 * tightness * tightness * (mean_residual / cap).max(0.0) + 10.0 / crowd;
        // Early stream: opening bins is cheaper
        score -= 20.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space)
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 0.5;

    // Harmonic class of post_residual: prefer residuals in "usable" classes
    // (residuals that many item sizes can still fill)
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect closure
    } else {
        // modulo-10 class logic: residuals divisible by 10 are reusable
        let cls = pr % 10;
        if cls == 0 {
            score -= 5.0;
        } else if cls <= 3 {
            score += 4.0; // awkward sliver
        } else {
            score += cls as f64 * 0.3;
        }
        // integer-division thresholds: residual large enough for typical items
        if pr >= 50 {
            score -= 3.0;
        } else if pr < 10 {
            score += 6.0; // dead space penalty
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 / (slack + 1.0);
        } else {
            score += 3.0; // next item won't fit here; bin becomes dead-ish
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0; // default penalty for opening new bin
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // early stream: more willing to open bins
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer filling bins with low mean residual (aging bins)
    if (mean_residual - post_residual as f64).abs() > 0.0 {
        if (post_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

