        score += dead;

        // Reward near-perfect fits superlinearly (waste minimization).
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * fill_ratio * fill_ratio;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // consolidation is possible; more bins => higher baseline cost.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 10.0 + 0.8 * open_bins_count as f64;

        // If the item leaves a residual that pairs well with the lookahead item,
        // opening a new bin becomes attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Large items are better placed in a fresh bin than fragmenting
        // a partially-filled one.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Lookahead synergy: if the post residual exactly accommodates the next
    // item, this placement is ideal (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial synergy: keep usable room for the next item.
        score -= 4.0;
    }

    // Mean-residual coupling: bins far below the mean residual are better
    // consolidation targets (reduce residual variance across bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Late in the stream, avoid opening new bins; squeeze into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: this bin will be filled perfectly next step
        } else if post_residual > next_item_size {
            let slack = pr - nr;
            score -= (60.0 * (-slack / 25.0).exp()).max(0.0);
        } else {
            // next item cannot fit here; penalize dead space mildly
            score += 0.5 * (nr - pr);
        }
    }

    // Relative-to-mean residual coupling: bins tighter than the mean
    // are more valuable to fill.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (pr - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Late in the stream, be more conservative: prefer tighter fills,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += 40.0 + 200.0 * progress;
        // Opening a new bin is fine if it enables a perfect chain for next item.
        if next_item_size > 0 && bin_capacity == next_item_size {
            score -= 300.0;
        }
    }

    // Prefer filling bins that are already mostly full.
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64).sqrt();
    } else {
        score -= 25.0; // perfect fill
    }

    // Last-chance bin: strongly prefer using it before it becomes dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            // Next item can also go here: reward proportional to how well it packs.
            let pair_waste = post_residual as f64 - next_item_size as f64;
            score -= 12.0 - pair_waste * 0.15;
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 0.25;
        }
        // If next item exactly fills post-residual, big bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: any residual is pure waste.
        score += post_residual as f64 * 0.5;
    }

    // Relative fit quality: fraction of bin used by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Penalize bins whose residual deviates strongly from mean (keep diversity).
    let dev = bin_residual as f64 - mean_residual;
    score += dev.abs() * 0.05;

    // Time horizon: early in stream, be more willing to open new bins / keep
    // flexibility; late in stream, squeeze items into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 15.0 * (1.0 - progress);
        // Opening a new bin is bad if few bins fit the item elsewhere.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Very large items justify a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Existing bin: reward more heavily late in the stream.
        score -= 8.0 * progress;
    }

    // Many open bins: discourage proliferation, favor consolidating into existing ones.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but weight residual cost non-linearly over time.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Smooth superlinear penalty for small-but-nonzero dead space,
    // strengthened as the stream progresses.
    let dead = 1.0 - norm_pr;
    score += 40.0 * (1.0 - dead) * (1.0 - dead) * progress;

    // Reward near-perfect fills with a smooth bump around post_residual ~ 0..5.
    let perfect = (-norm_pr * 18.0).exp();
    score -= 25.0 * perfect * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 30.0 * (1.0 - fit_quality) * (1.0 + progress);
    }

    // Lookahead: penalize leaving residual that barely fails the next item
    // (smooth ramp near the boundary).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 && gap > -12.0 {
            score += 12.0 * (1.0 + gap / 12.0) * (1.0 + gap / 12.0) * (0.5 + progress);
        }
        // Reward residual that can still host the next item.
        if gap >= 0.0 && gap < 25.0 {
            score -= 6.0 * (1.0 - gap / 25.0) * (0.3 + 0.7 * progress);
        }
    }

    // Mild penalty when this bin is much tighter than average (preserve loose bins
    // for future large items), smoothed with a logistic gate.
    let diff = (mean_residual - pr) / cap;
    let gate = 1.0 / (1.0 + (-8.0 * diff).exp());
    score += 10.0 * gate * (0.4 + 0.6 * progress);

    // Slight bias against proliferating bins late in the stream.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left after placement

    // Class boundaries: "dead space" thresholds at 1/8, 1/4, 1/2 of capacity.
    // Residuals below 1/8 are nearly unusable (item sizes >= 10 => min item 10/100 = 0.1).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always excellent
    } else if post_residual < 10 {
        score -= 45.0; // unusable sliver: as good as a perfect fit
    } else if frac <= 0.125 {
        score -= 25.0; // dead-space class: bin effectively closed
    } else if frac <= 0.25 {
        score -= 10.0; // quarter class: only fits small items
    } else if frac <= 0.5 {
        score += 0.0; // half class: neutral
    } else {
        score += 8.0; // more than half left: bin still very usable
    }

    // Integer-division harmonic coupling: does post_residual accommodate the
    // next item? Reward bins whose leftover matches the lookahead's class.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how tightly next item fills the leftover
        let tight = 1.0 - (next_item_size as f64 / post_f);
        score -= 20.0 + 15.0 * tight;
    } else if next_item_size > 0 {
        // Next item cannot use this leftover; penalize proportionally to waste
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post_residual is huge waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item
    // leaves a "harmonic" residue that pairs with common sizes, or few bins open.
    if bin_residual == bin_capacity {
        let mut nb = 40.0;
        // Prefer new bin when stream is early (room to consolidate later)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb -= 15.0 * (1.0 - progress);
        // Prefer new bin when many bins are open and mean residual is low
        // (existing bins are nearly full anyway)
        nb -= (open_bins_count as f64).min(20.0) * 0.5;
        nb -= mean_residual * 0.2;
        // Harmonic check: does the item leave a residue in a "good class"?
        if post_residual >= 10 && post_residual < 30 {
            nb -= 10.0; // residue likely reusable by small items
        }
        score += nb;
    }

    // Mild preference for tighter fits among ordinary bins
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty proportional to wasted capacity.
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 2.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (high fill ratio of the residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already low; encourage consolidation.
    score += open_bins_count as f64 * 0.8;

    // If the next item would fit into the post-residual, reward leaving
    // a "useful" gap; otherwise penalize a gap that helps nothing.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when existing residuals are poor
    // (mean residual small) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: zero waste is highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills
    // the residual left behind (a perfect 2-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual && post_residual > 0 {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves a new residual; mild penalty
            // proportional to the mismatch so tight chains are preferred.
            score += (post_residual - next_item_size) as f64 * 0.25;
        } else {
            // Next item cannot use this bin's leftover: leftover becomes
            // terminal dead space; add a modest penalty.
            score += 8.0;
        }
    }

    // Small nonzero residuals are classic dead space (min item is small);
    // penalize unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: slightly penalized so good existing fits win,
    // but increasingly attractive when open bins are nearly full
    // (high mean residual means little usable room left overall).
    if bin_residual == bin_capacity {
        score += 12.0 - mean_residual * 0.15;
        // Late in the stream, avoid spawning bins for marginal gain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Best-fit coupling: prefer bins tighter than the current mean residual
    // (keeps large residual bins available for large future items).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to hold a typical future item
    // (items 1..100 unknown; small leftovers < ~20 are usually waste).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 8.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Global state coupling: if mean residual is high, spread items less;
    // favor bins below mean residual (tighter bins get priority).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more selective (avoid wasting big bins);
    // late in the stream, pack greedily into anything that fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it's genuinely better,
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64);
        // but if no open bin fits well (post_residual tiny on others handled elsewhere),
        // relax: when many bins open and mean residual low, opening is less bad.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual (quadratic penalty on waste)
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 2.0 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward bins whose residual is close to the item (good fill ratio)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalty when many bins are open and residual is large (fragmentation)
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Lookahead coupling: if the next item could use the post-residual, reward this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let chain = next_item_size as f64 / cap;
        score -= 5.0 * chain * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 / cap);
    }

    // Discourage bins far from the mean residual (outlier dead space)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate bias: prefer reusing open bins early, allow new bins late
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by small
    // granularity values are more reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        // Class 1: post_residual divisible by 10 (typical item granularity)
        if pr % 10 == 0 {
            score -= 30.0;
        }
        // Class 2: divisible by 5
        if pr % 5 == 0 {
            score -= 8.0;
        }
        // Class 3: divisible by 20 (fits two more medium items)
        if pr % 20 == 0 {
            score -= 12.0;
        }
        // Dead-space harmonic classes: small odd residues are hard to fill
        if pr < 10 && pr % 2 == 1 {
            score += 25.0;
        }
        // Residual in the "awkward band" 11..19 is a classic dead zone
        if pr > 10 && pr < 20 {
            score += 15.0;
        }
    }

    // Integer-division thresholds: how many items of average size (~30)
    // still fit after placement.
    let slots = pr / 30;
    score -= slots as f64 * 10.0;

    // Coupling with lookahead item: harmonic match between post_residual
    // and next_item_size via exact divisibility or near-fit.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, more so on exact/near-exact fit.
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 60.0;
            } else if slack % 10 == 0 {
                score -= 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit: penalize leaving a residue it can't use,
            // scaled by how badly it misses (integer division ratio).
            let miss = next_item_size - pr;
            score += (miss as f64) * 0.5;
            if miss < 10 {
                score += 20.0; // near-miss: residue is nearly useless
            }
        }
        // Harmonic pairing: post_residual equals a multiple of next_item_size
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins are crowded (harmonic fraction of capacity used).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin.
        score += 120.0;
        // If existing bins are mostly full (mean residual low), opening is fine.
        let fill_fraction = mean_residual / bin_capacity as f64;
        if fill_fraction < 0.25 {
            score -= 100.0;
        }
        // Many open bins with plenty of slack: discourage new bins.
        score += open_bins_count as f64 * 2.0;
        // Large items early in the stream benefit from a fresh bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 && progress < 0.3 {
            score -= 30.0;
        }
        // If next item is large and this bin would be nearly consumed, fresh bin is good.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 40.0;
        }
    } else {
        // Reward tight fills in existing bins (harmonic capacity fraction).
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used_frac * 20.0;
        // Prefer bins whose residual is below the mean (packing toward fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Mild penalty for hoarding many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below min item size 1..100 => anything < ~10 is dead) are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 200.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fit_ratio;

    // Penalize mid-sized dead gaps that likely can't fit typical future items.
    if post_residual > 0 && post_residual < item_size {
        score += 30.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: opening a bin is costly; add pressure proportional to
    // open bins count so we only open when placement elsewhere is truly bad.
    if bin_residual == bin_capacity {
        score += 120.0 + 15.0 * open_bins_count as f64;
        // But if no open bin fits well, opening is fine: reward large item packing
        if item_size as f64 > 0.6 * capacity {
            score -= 60.0;
        }
    }

    // Open bins pressure: discourage spreading when many bins are already open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / capacity);

    // Lookahead: if next item would fit into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below mean residual => tighter bin, better consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Slight stream progression bias: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / capacity);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-exact fits (post_residual close to zero).
    let tightness = post_residual as f64 / cap;
    score -= 30.0 * (-tightness * 12.0).exp();

    // 2-step lookahead: reward post_residual that exactly accommodates next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 25.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 12.0 * (-slack * 8.0).exp(); // good chain fit
        } else {
            // Next item won't fit here: penalize proportional to leftover waste.
            score += 6.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / cap);
        }
    }

    // Relative-to-mean residual shaping: prefer bins below mean residual (tighter bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 20.0;               // base penalty for opening a new bin
        score -= 25.0 * fill;        // large items justify fresh bins
        if fitting_bins_count == 0 {
            score -= 40.0;           // forced: no open bin fits
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 10.0;           // fresh bin at least chains with next item
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Dead-space penalty: post_residual that likely cannot fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if next item is large and would leave this bin stranded, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            let waste_gap = (next_item_size - post_residual) as f64;
            score += 0.15 * waste_gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Bin already well-loaded: keep filling it (encourage consolidation).
    let fill = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 15.0 * fill;

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0));
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins close to the mean residual (balanced use),
    // penalize outliers that strand capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Time horizon: early in stream, be more willing to open new bins (low penalty);
    // late in stream, squeeze into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score += 35.0 * t;
        // But if no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        score -= 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr;

    // Non-linear polynomial coupling: waste curvature grows with stream progress
    // (late in the stream, dead space is more costly since fewer items remain to fill it).
    let curvature = x * (1.0 - x);           // peaks mid-range, vanishes at perfect fit / empty
    score += curvature * (40.0 + 60.0 * progress);

    // Penalize post-residuals that are small but nonzero (unusable slivers),
    // with smooth exponential shaping rather than a piecewise cutoff.
    let sliver = (-6.0 * x).exp();
    score += sliver * 25.0 * (1.0 - progress * 0.5);

    // Reward tight fits: post_residual near 0 gets a smooth bonus.
    score -= (1.0 - x).powi(6) * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if the next item can exactly use this post-residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= (-(diff / 10.0).powi(2)).exp() * 35.0;
        // If next item fits comfortably, mild extra reward.
        if pr >= nx {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // New-bin candidate (empty bin): penalize opening new bins when open bins exist,
    // penalized more early in the stream; allow late opening when fragmentation is high.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).max(0.0);
        score += 20.0 + 30.0 * (1.0 - progress) - 40.0 * frag * progress;
    }

    // Mild preference for filling already-open bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small residue class" (<= 10) are nearly perfect, reward them.
    let residue_class = post_residual % 10;
    if post_residual <= 10 {
        score -= 30.0; // near-perfect packing
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize dead space in awkward classes: residues in (20,50) are hard to fill.
    if post_residual > 20 && post_residual <= 50 {
        score += 6.0 + residue_class as f64 * 0.3;
    }

    // Integer-division threshold: which harmonic slot (quarter of capacity) does
    // the post-residual land in? Lower slots are better.
    let quarter = post_residual / 25;
    score -= (3 - quarter.min(3)) as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in the post residual
    // (harmonic pairing), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residue; penalize proportional to waste potential
            score += (next_item_size - post_residual).min(50) as f64 * 0.15;
        }
        // modulo pairing: next item shares residue class with post residual
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current item is large
    // relative to mean residual (poor fits everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = item_size as f64 / cap;
        if fit_ratio > 0.7 || (fitting_bins_count == 0 && progress < 0.3) {
            score -= 20.0;
        } else {
            score += 10.0 + fit_ratio * 15.0;
        }
    }

    // Slight preference for tighter bins overall (low mean residual => bins well used).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Tie-breaker by step parity class to diversify exploration mildly.
    if step_index % 7 == 0 && post_residual > 60 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone_max {
        // Penalty ramps up as the gap gets smaller (less likely to be reused).
        score += (dead_zone_max - post_residual as f64) * 8.0;
    }

    // Perfect fit: subtract heavily to strongly favor zero-waste placements.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave a gap exactly matching the next item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap slightly larger than the next item but unusable by it.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual as u64) < (next_item_size as u64) + 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits (avoids opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items into fresh space;
    // favor filling existing bins and penalize opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate: allow opening a new bin only when all open bins would create
    // dead space (poor fits). Otherwise penalize the fresh bin so existing bins are used.
    if bin_residual == bin_capacity {
        let poor_fit_exists = (post_residual as f64) < dead_zone_max && item_size < bin_capacity;
        if !poor_fit_exists {
            score += 20.0 + pressure;
        } else {
            score -= 5.0;
        }
    }

    // Mild bonus for bins whose residual is close to the mean (keeps residuals balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual == next_item_size is perfect
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits tightly with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space that neither the next item nor anything small can use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: prefer bins whose residual stays near the mean
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Mild penalty for opening a new bin when open bins exist and fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild penalty when many alternatives exist, to keep options open.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low (bins are scarce).
    let scarcity = (mean_residual / cap).max(0.0);
    score += 10.0 * scarcity;

    // Time horizon: early in the stream, be more willing to spread items (favor new bins
    // slightly less), late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // Prefer using existing open bins over opening new ones, scaled by how many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it creates a perfect-fit future or
        // open bins are very fragmented.
        score += 20.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size && item_size >= 50 {
            score -= 25.0; // opening a bin for a big item with room for the next is fine
        }
    } else {
        score -= 5.0;
    }

    // Slight preference for bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: residual weight grows over stream progress
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress;
    score += 40.0 * poly;

    // Penalize near-perfect waste (dead space) smoothly
    if post_residual > 0 && post_residual < item_size {
        let dead = post_residual as f64 / item_size as f64;
        score += 12.0 * dead * (1.0 - dead);
    }

    // Reward last-chance bins
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residual that fits next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.3 * gap * (0.5 + progress);
    }

    // Slight bias toward consolidating into bins with low mean residual
    score += 0.2 * mean_residual * (1.0 - progress);

    // New-bin candidate penalty: prefer existing bins, more so early
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space into modulo buckets.
    // Small residues that cannot host the next item are dead space -> penalize.
    let fits_next = next_item_size > 0 && post_residual >= next_item_size;
    if next_item_size > 0 {
        if fits_next {
            // Reward proportionally to how snugly the next item would fit
            score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
            // Extra reward when next item exactly fills the resulting bin
            if post_residual == next_item_size {
                score -= 50.0;
            }
        } else {
            // Dead space for the lookahead item: penalize by its class
            let class = post_residual % 10; // harmonic bucket of dead space
            score += 5.0 + class as f64 * 0.5;
            // Very small dead space (<10) is nearly unusable given min item size 1..100
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Integer-division thresholds on post_residual: quarter classes of capacity
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        // residue in lowest quarter: mostly dead unless perfect fit already handled
        score += 8.0;
    } else if post_residual <= 2 * quarter {
        score += 2.0;
    } else if post_residual <= 3 * quarter {
        score -= 4.0; // sweet spot: roomy but not wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 60.0;
        // but if this bin is the only fitting one and the fit is bad, opening may win:
        // penalize more when many open bins exist with slack (fragmentation signal)
        if fitting_bins_count >= 1 && mean_residual > 0.5 * bin_capacity as f64 && open_bins_count > 2 {
            score -= 30.0;
        }
    }

    // Progress coupling: late in the stream, tighten packing (avoid waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Penalize bins far from the mean residual (fragmented outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Modulo-3 harmonic class of item_size vs post_residual alignment
    if post_residual % 3 == item_size % 3 && post_residual >= item_size {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to be useful are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 200.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear tightness reward (borrowed from best): quadratic fill bonus.
    let tightness = 1.0 - (post_residual as f64 / capacity);
    score -= 30.0 * tightness * tightness;

    // Reward tight fits relative to the residual being filled.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fit_ratio;

    // Penalize mid-sized dead gaps that likely can't fit typical future items.
    if post_residual > 0 && post_residual < item_size {
        score += 30.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: opening a bin is costly; add pressure proportional to
    // open bins count so we only open when placement elsewhere is truly bad.
    if bin_residual == bin_capacity {
        score += 120.0 + 15.0 * open_bins_count as f64;
        // Relax pressure when mean residual is very low (open bins are nearly full).
        if mean_residual < 15.0 {
            score -= 40.0;
        }
        // Large items pack cleanly into fresh bins.
        if item_size as f64 > 0.6 * capacity {
            score -= 60.0;
        }
    }

