        // stranded sliver below the next item, penalize harder — consolidating
        // loose bins matters more than leaving unusable gaps.
        if fleet_looseness > 0.12 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap * fleet_looseness;
        }
