        // Fresh-bin lookahead — only open if the next item can chain
        // into the leftover of this placement, or the residual would be tiny.
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0; // stranded sliver that can't chain
