            if slack <= 3 {
                score -= 14.0; // near-perfect dual fit
            } else if slack > 45 {
                score += 6.0; // overly loose fit wastes space
            }
        }
    }

    // Scarcity-aware consolidation — sharpen preference for the tightest bin.
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / cap);
    }

    // MUTATION (carried): residual-band matching — among fitting bins, reward
    // the one whose post-residual lands in the "reusable band" (>= next item
    // but not wastefully large), scaled by stream progress.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 6.0 * (1.0 + 0.5 * progress);
        }
    }

    // MUTATION (new): dead-space ratio targeting for open bins — penalize a
    // fitting bin whose post-residual is stranded (below the mean item size
    // and below next item), proportional to how much of the bin it strands.
    // This complements the fresh-bin sliver logic by pushing slivers out of
    // contention among open bins too.
    if bin_residual < bin_capacity && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded_frac = (next_item_size - post_residual) as f64 / cap;
        if post_residual < 15 {
            score += 10.0 * stranded_frac * 100.0 * 0.2; // bounded nudge toward avoiding tiny stranded tails
        }
    }

    // MUTATION (new): two-step chainability for open bins — if the post-residual
    // can host the next item AND the remainder after that is still >= a small
    // item (>= 5), this bin is a strong multi-item host; reward scaled by how
    // much total future volume it can absorb.
    if next_item_size > 0 && post_residual > next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder >= 5 {
            score -= (remainder.min(30) as f64) * 0.25;
        }
    }

    score
}

