    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // MUTATION (gen 10): dead-space-ratio minimization — score bins by the
    // fraction of residual that is genuinely unusable. A residual that
    // cannot hold the next item is dead weight; scale the penalty by how
    // much of the bin's remaining space is stranded, and reward bins whose
