    if next_item_size > 0 && bin_residual < bin_capacity {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if pr > 0.0 {
            let stranded_frac = (1.0 - (pr / ni).min(1.0)) * (pr / cap);
