    // progress since chain value decays late in the stream.
    if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
        let chain = (post_residual / next_item_size) as f64;
        score -= 10.0 * chain.min(4.0) * (1.0 - 0.4 * progress);
