    // zone effectively retire the bin cleanly; reward scaled by scarcity.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
