    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 18): dead-zone gradient on unusable stranded slack —
    // when the post-residual can't hold the next item and the shortfall is
    // small (nearly-fit waste), penalize proportionally to how close it came;
    // this steers selection away from bins that strand 1–12 units of dead space,
    // directly targeting the diagnosed residual/dead-space weakness.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 12.0 {
            let pool = (mean_residual * open_bins_count as f64).max(next_item_size as f64);
