pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins that end with near-zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this one; closer match is better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement — penalize dead space
            // that is too small to be useful for the next item.
            let dead = nxt - post;
            score += 0.5 * dead;
        }

        // Chain bonus relative to mean residual: placing here keeps residuals
        // balanced if post_residual is near the mean of open bins.
        let mean_gap = (post - mean_residual).abs();
        score += 0.3 * mean_gap;

        // If next item fits the post residual better than it would fit the
        // current residual, reward (this bin absorbs the item that pairs well).
        if post_residual >= next_item_size && bin_residual < next_item_size {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        // Extra reward if the fit is tight.
        if post_residual <= 20 {
            score -= 100.0;
        }
    }

    // Penalize wasteful placements: large post residual that is unlikely to be
    // usable (items are 1..100, so residual < 10 is nearly dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Slight preference for opening new bins early in the stream when many bins
    // are already open with high mean residual (avoid fragmenting).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral baseline with mild penalty so it only wins
        // when open bins have poor fits.
        score = bin_capacity as f64 * 0.5 + 100.0 - 50.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin can trivially hold the next item too.
            score -= 20.0;
        }
        // If only this new bin "fits", it's forced anyway.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

