            score += 8.0;
        }
    }

    // Dual-fit shaping: prefer bins whose post-residual is closest to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * ((next_item_size - post_residual) as f64 / cap) * (fitting_bins_count as f64);
    }

    // Near-exact fit bonus.
    if post_residual > 0 && post_residual <= 2 {
        score -= 20.0;
    }

    // Dead-space ratio shaping — steer toward dual/triple fits.
    if post_residual > 0 && next_item_size > 0 {
        let strand = (post_residual as f64 / cap) * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        if post_residual < next_item_size {
            score += 18.0 * strand;
        } else {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 14.0;
            } else if slack > 45 {
                score += 6.0;
            }
