pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Residuals divisible into small harmonic classes (e.g. multiples of 10 or 5)
    // are more likely to host future items.
    let harmonic10 = (post_residual % 10 == 0) as f64;
    let harmonic5 = (post_residual % 5 == 0) as f64;
    score -= 6.0 * harmonic10 + 2.5 * harmonic5;

    // Fractional capacity bands: classify post_residual as a fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead space band: leftover below 10% of capacity is nearly unusable (items >= 10... but sizes 1..100)
    if frac < 0.10 && post_residual > 0 {
        score += 12.0;
    }
    // Sweet spot band: 25-50% leftover is highly reusable
    if frac >= 0.25 && frac <= 0.50 {
        score -= 5.0;
    }

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 25.0;
    }

    // Integer division thresholds: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: leftover can host the lookahead item
            score -= 4.0;
            // Bonus if leftover after the next item would again be small (tight chaining)
            let chain_post = post_residual - next_item_size;
            if chain_post % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // Leftover cannot host next item: penalize proportionally to wasted potential
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin; grows with number of already open bins
        let mut new_bin_cost = 22.0 + 1.5 * (open_bins_count as f64);
        // If the item is "large" relative to capacity, opening fresh is natural
        if (item_size as f64) / (bin_capacity as f64) > 0.6 {
            new_bin_cost -= 10.0;
        }
        // If many bins fit the item, no reason to open a new one
        if fitting_bins_count >= 3 {
            new_bin_cost += 12.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost += 8.0 * progress;
        score += new_bin_cost;
    }

    // Mild tie-break: prefer bins whose residual deviates favorably from the mean
    // (packing into below-mean-residual bins keeps large gaps available)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 2.0 * dev;

    // Modulo-class penalty: post residuals that are odd or in awkward classes (e.g. 1..9 mod 10
    // with small values) are hard to fill with integer item sizes.
    let class = post_residual % 10;
    if class >= 1 && class <= 4 && post_residual < 20 {
        score += 6.0;
    }

    score
}

