        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
                // Waste-anticipation: leftover sliver 1..=4 after next item retires cleanly.
                let after = post_residual - next_item_size;
                if after >= 1 && after <= 4 {
                    score -= 3.0 + 2.0 * (4 - after) as f64;
                } else if after > 10 {
                    score += 3.0 + 0.05 * after as f64;
                }
            } else {
                let stranded = (next_item_size - post_residual) as f64;
                if stranded < 8 {
                    score += 4.0 + 0.5 * stranded;
                } else {
                    score -= 2.0;
                }
            }
        }
        // Late-stream discipline: opening bins late is costly.
        if progress > 0.6 && mean_residual < 25.0 {
            score -= 8.0 * progress;
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // Large next item stranded by small current item: keep fresh bin available.
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
        // Collective residual pool can absorb the next item: don't open a new bin.
        if mean_residual * (open_bins_count as f64) >= next_item_size as f64 && item_size < next_item_size {
            score += 8.0;
        }
        // Fresh-bin fill guarantee: penalize opening for items that strand a mid dead gap.
        let fresh_left = capacity - item_size as f64;
        if fresh_left > 0.0 && fresh_left < 0.25 * capacity && next_item_size as f64 > fresh_left {
            score += 18.0 * (1.0 - progress);
        }
    }

    // Open bins pressure: discourage spreading when many bins are already open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / capacity);

    // Lookahead: graded reward/penalty based on next item fit quality.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0 + 10.0 / (fitting_bins_count as f64).max(1.0);
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
            // Pair-packing anticipation: near-perfect two-item fill.
            if post_residual - next_item_size < 5 {
                score -= 35.0;
            }
        } else {
            score += 8.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
        // Triple-chain anticipation: residual that holds next item plus a small follow-up.
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next > 0 && after_next <= 12 {
            score -= 12.0;
        }
        // Dual-fit shaping: bins whose post-residual undershoots next item are penalized
        // proportionally to alternatives.
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0 * ((next_item_size - post_residual) as f64 / capacity)
                * (fitting_bins_count as f64);
        }
    }

    // Mean residual coupling: prefer bins tighter than the mean, with kick.
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;
    if dev > 20.0 {
        score -= 6.0;
    }

    // Stream progression bias: later in stream, consolidate more aggressively.
    score += 20.0 * progress * (post_residual as f64 / capacity);

    // Early-stream pickiness: scale score to be more selective at the start.
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Residual-band matching — reward post-residuals in the reusable band
    // around the next item size; penalize slack beyond it.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * progress;
        if (slack as f64) <= band {
            score -= 6.0 * (1.0 + 0.5 * progress);
        } else {
            score += (0.06 + 0.04 * (1.0 - progress)) * ((slack as f64) - band);
        }
    }

    // Exact-sweep reward — clean bin retirement frees capacity.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Capacity-scaled waste anticipation — dead gap just below next item
    // is worse when the collective residual pool could absorb the next item elsewhere.
    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
            }
        }
    }

    // Fleet-fit conservation — protect roomy residuals for large next items.
    if next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / capacity);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Scarcity-weighted exact-fit gate — few alternatives and a tight
    // post-residual sharpens preference for this bin.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / capacity);
    }

    // Adaptive scarcity gate — when the only fitting bin would strand the
    // next item, soften the penalty early in the stream.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack beyond the
    // next item, damped by the absorbable residual pool.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
        // Residual homogenization pull — target post-residual near the fleet mean.
        let dist = (post_residual as f64 - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly,
    // amplified by scarcity of alternatives.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
        // Pair-fit anticipation: two-step chain that leaves a small follow-up gap.
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Perfect-chain jackpot — post-residual exactly consumes the next item,
    // strongest when alternatives are scarce.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0)) * (1.0 + progress);
    }

    // Variance-aware dead-space shaping — when the fleet's residuals are
    // dispersed, penalize stranding small unusable gaps harder.
    if mean_residual > 30.0 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }

    // Mid-gap triage — residuals that can't hold the next item but exceed the
    // small-item band are graded waste, stronger early.
    if post_residual >= dead_threshold as u32 && next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap >= 10.0 {
            let pool = (mean_residual * open_bins_count as f64).max(1.0);
            let escapable = (gap / pool).min(1.0);
            score += (4.0 + 0.25 * gap) * escapable * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // MUTATION (gen 20): dual-fit consolidation — when two or more bins fit,
    // sharpen the preference for the one whose post-residual most closely
    // matches the next item, combining fine residual fitting with lookahead.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let closeness = 1.0 - (post_residual - next_item_size) as f64 / capacity;
        score -= 5.0 * closeness * closeness;
    }

    // MUTATION (gen 20): stranded-gap hard gate — a post-residual that cannot
    // hold the next item and is far below the mean residual is pure dead space;
    // penalize proportionally to how much of the bin is wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
        let waste_frac = post_residual as f64 / capacity;
        score += 12.0 * waste_frac * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill: strongly reward
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Last chance: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Many alternatives: mild penalty to keep large residuals for future items.
        score += 3.0 * (fitting_bins_count as f64).min(6.0);
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.35 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate: only attractive when the item is huge or current bins are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        score += 18.0 - 22.0 * mean_fill;
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0; // next item won't fit here; dead space likely
        }
    }

    // Slight mid-stream tightening: as the stream progresses, favor compacting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic + cubic shaping on fill fraction after placement.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness - 20.0 * tightness * tightness * tightness;

    // Dead-space waste: penalize leftovers too small for typical items.
    if post_residual > 0 && post_residual < 20 && next_item_size != post_residual {
        let scarcity = 1.0 + 0.5 / (fitting_bins_count as f64).max(1.0);
        score += (25.0 + (20 - post_residual) as f64) * scarcity;
    }

    // Lookahead: exact chain fit is a jackpot, amplified by scarcity.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0 + 10.0 / (fitting_bins_count as f64).max(1.0);
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 8.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 35.0;
        }
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next > 0 && after_next <= 12 {
