    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — when the next item plus a known small follow-up
    // would exactly retire the bin, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 20): dead-space density penalty — waste normalized by
    // remaining fleet capacity; large slack is worse when the fleet is tight.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 12.0 {
            let fleet_cap = mean_residual * (open_bins_count as f64).max(1.0) + slack;
            let density = slack / fleet_cap.max(1.0);
            score += 14.0 * density * density * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 20): two-step chain — if post-residual can host the next
    // item AND the remainder still fits a small follow-up, reward the chain.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after > 0 && after <= mean_residual.max(1.0) {
            score -= 3.0 * (1.0 - after as f64 / mean_residual.max(1.0)) * (0.5 + progress);
        }
    }

    // MUTATION (gen 20): new-bin gate refinement — penalize opening a bin whose
    // post-residual strands a large unusable gap relative to the next item,
    // while easing the gate late in the stream when consolidation matters most.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let pr = post_residual as i64 - next_item_size as i64;
        if pr > 20 {
            score += 0.35 * (pr as f64 - 20.0) * (1.0 - 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect next-item match gets big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item can still fit here: mild reward proportional to closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item: penalize.
        score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 10.0;
    }

    // Prefer bins that deviate from mean residual (tight bins get priority).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

