    // Reward tight fits: small post-residual is good, but waste nothing on exact fits.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fit_ratio; // prefer bins where item fills a large fraction
        // Penalize small unusable slivers (dead space that few future items can use)
        if post_residual < 10 {
            score += 25.0; // tiny dead space is nearly worthless
        } else if post_residual <= 20 {
            score += 5.0;
        }
    }

    // Lookahead coupling: if next item fits into the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // keeps a useful chain alive
            let chain_fill = (item_size + next_item_size) as f64 / bin_residual as f64;
            if chain_fill > 0.95 {
                score -= 20.0; // near-perfect two-item packing
            }
        } else {
            score += 8.0; // post-residual likely wasted w.r.t. lookahead
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Penalize new bins when a decent fit exists elsewhere.
        let best_existing_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        if best_existing_fit > 0.0 {
            // compare: prefer new bin only if item is small relative to capacity
            // (small items leave versatile residuals) and many bins are open.
            let small_item_bonus = (bin_capacity - item_size.min(bin_capacity)) as f64;
            score += 15.0; // base cost of opening a new bin
            if item_size as f64 > 0.7 * bin_capacity as f64 {
                score += 10.0; // big items: better to squeeze into existing space
            }
            if small_item_bonus > 70.0 && open_bins_count > 4 {
                score -= 10.0; // occasionally explore fresh bins for small items
            }
            // Late in the stream, avoid opening new bins.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 * progress;
        } else {
            score -= 50.0; // nothing fits anywhere: new bin is mandatory
        }
    }

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidation into existing bins rather than spreading.
    if open_bins_count > 0 {
        let mean_r = mean_residual.max(0.0);
        if mean_r > 40.0 && bin_residual < bin_capacity {
            score -= 6.0; // there is lots of slack around; use it
        }
        if open_bins_count > 10 {
            score -= 3.0; // consolidation pressure when bin count grows
        }
    }

    // Mild time-horizon adaptation: early on, be exploratory (favor balanced residuals);
    // late, be greedy (favor minimal post_residual, already implicit).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && bin_residual < bin_capacity {
        // early: prefer leaving residuals near the mean item size for flexibility
        let target = 45.0;
        score += 0.2 * (post_residual as f64 - target).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
