            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // MUTATION: continuous dead-space gradient — smooth waste curve on slack,
    // sharpened: pool-absorbable slack penalized more aggressively mid-stream.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.14 * (slack - 3.0).min(60.0) * absorbable * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // MUTATION: near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // MUTATION: residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 13): pair-fit anticipation — when the next item plus a
    // known small follow-up would exactly retire the bin, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // MUTATION (gen 13): scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 21): mid-band slack trap — post-residuals in the 11..=30
    // range that cannot absorb the next item strand capacity; penalize
    // proportionally to how far the next item overshoots the leftover.
    if next_item_size > 0 && post_residual >= 11 && post_residual < next_item_size {
        let overshoot = (next_item_size - post_residual) as f64;
        if overshoot <= 25.0 {
            score += 0.30 * overshoot * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 21): two-step chain viability — when the residual after
    // placing the next item lands in a small reusable sliver (1..=8), reward
    // the bin for supporting a longer retirement chain.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 8 {
            let chain_value = (9.0 - after as f64) / 8.0;
            score -= 5.0 * chain_value * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 21): new-bin gate tuned by aggregate stranded capacity —
    // open a fresh bin only when existing residuals collectively cannot host
    // the next item, otherwise lean harder on consolidation.
    if bin_residual == bin_capacity {
        let fleet_capacity = mean_residual * (open_bins_count as f64).max(1.0);
