            score -= 14.0 * (1.0 - progress);
        } else if fleet_capacity > next_item_size as f64 * 1.5 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 0.8 * progress) + 0.6 * pr_norm * pr_norm * (1.0 - progress) + 0.4 * pr_norm.powi(3) * progress;

    let mut score = poly * cap;

    // Reward near-perfect fits (small post_residual) with smooth exponential shaping
    score -= 12.0 * (-pr / 8.0).exp();

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 6.0 + (ns - pr) * 0.5;
        } else {
            // reward leaving exactly usable space for the next item
            score -= 4.0 * (-(pr - ns).abs() / 10.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.3;

    // Pull toward mean residual to balance load across bins
    score += 0.2 * (pr - mean_residual).abs();

    // New-bin candidate: make it mildly unattractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 8.0 - 5.0 * progress;
    }

    score
}

