        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — two-step lookahead toward exact retirement.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 21): item-to-residual co-fit gradient — when the item
    // nearly fills the residual exactly, sharpen the preference proportionally
    // to the wasted gap, coupling fine-grained fitting with lookahead.
    if bin_residual < bin_capacity {
        let gap = bin_residual - item_size;
        if gap > 0 && gap <= 6 {
            score -= (7.0 - gap as f64) * (1.0 + 0.4 * progress);
        }
        // MUTATION: mid-gap dead-space ramp — penalize gaps that neither fit
        // the next item nor retire the bin, scaled by fleet slack.
        if next_item_size > 0 && gap > 6 {
            let usable = gap as f64 >= next_item_size as f64;
            if !usable {
                let fleet = (mean_residual * open_bins_count as f64).max(1.0);
                let absorb = (fleet / next_item_size.max(1) as f64).min(2.0);
                score += 1.5 + 0.08 * (gap as f64) * absorb;
            }
        }
    }

    // MUTATION: next-item gating of fresh bins — if the next item is small and
    // the fleet has plenty of room, strongly discourage opening a new bin.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fleet = mean_residual * open_bins_count as f64;
        if fleet > 3.0 * next_item_size as f64 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of common
    // item sizes is more likely reusable by future items.
    let post = post_residual;
    if post > 0 {
        // Residuals divisible by small harmonics (10, 20, 25, 50) are "usable classes".
        let harmonic_bonus = if post % 50 == 0 {
            18.0
        } else if post % 25 == 0 {
            12.0
        } else if post % 20 == 0 {
            10.0
        } else if post % 10 == 0 {
            7.0
        } else if post % 5 == 0 {
            3.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Penalize awkward dead space in the "hard" band: too small for the
        // minimum item (1..100 range => below ~15 is risky), but not zero.
        if post < 15 {
            score += (15 - post) as f64 * 2.5;
        }

        // Fraction-of-capacity class: residual in the top quarter is premium space.
        let quarter = bin_capacity / 4;
        if post >= 3 * quarter {
            score -= 8.0;
        } else if post >= 2 * quarter {
            score -= 4.0;
        }

        // Coupling with lookahead: if next item fits exactly into post_residual,
        // this is a perfect chain — reward strongly.
        if next_item_size > 0 {
            if next_item_size == post {
                score -= 25.0;
            } else if next_item_size <= post {
                // Next fits, but leaves a new residual: evaluate its harmonic class.
                let nr = post - next_item_size;
                if nr % 10 == 0 {
                    score -= 6.0;
                } else if nr < 10 {
                    score += 5.0;
                }
            } else {
                // Next item cannot use this bin's residual: mild penalty scaled
                // by how far off it is (integer-division gap).
                let gap = (next_item_size - post) as f64;
                score += gap * 0.15;
            }
        }
    } else {
        // Perfect fill: strongest possible reward.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize so we only open a new bin when open bins
    // fit poorly (large post_residual or none fit).
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if nothing currently fits, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Progress-based calibration: later in the stream, consolidation matters
    // more (fewer bins to carry to the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post as f64).abs() * 0.1;

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Small tie-break via open bin count: prefer spreading across fewer bins
    // when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
