        if item_size + next_item_size == bin_residual {
            score -= 400.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer bins already below average residual (consolidate waste).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to keep bins tidy;
    // late in the stream, squeeze harder into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 30.0 * (bin_residual as f64 / bin_capacity as f64);

