pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class A: near-perfect fit (<= 5% leftover) -> strong reward
    if post_residual <= bin_capacity / 20 {
        score -= 60.0;
    }
    // Class B: leftover can host a mid-size item (>= 20% capacity) -> moderate reward
    else if frac >= 0.20 {
        score -= 15.0;
    }
    // Class C: dead space (too small for typical items, > 5% but < 20%) -> penalty
    else {
        score += 25.0;
    }

    // Compatibility with lookahead: does post_residual still fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover remains usable for the next item: reward proportional to slack
            score -= 10.0 + 0.3 * ((post_residual - next_item_size) as f64).min(50.0);
        } else {
            // leftover cannot host next item -> dead space for at least one step
            score += 12.0 + 0.4 * next_item_size as f64;
        }
        // Harmonic pairing: post_residual exactly matches next item => excellent chain
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Integer-division threshold classes on next_item_size
        let nq = next_item_size / 10; // 0..10 harmonic decade
        match nq {
            0 | 1 => score -= 5.0,  // tiny next item: most residuals stay usable
            2 | 3 => score -= 2.0,
            6 | 7 => score += 6.0,  // large next item: fewer bins can host it
            8 => score += 10.0,
            _ => {}
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else (large item, crowded bins).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
        if item_size >= 60 && open_bins_count > 2 {
            score -= 8.0 + 0.2 * item_size as f64;
        } else {
            score += 30.0 + 5.0 * pressure.min(10.0);
        }
    }

    // Mild stream-position modulation: late in the stream, compactness matters more
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * (1.0 - frac);

    // Tie-break toward bins tighter than the mean residual
    score -= 0.1 * (mean_residual - pr).clamp(-50.0, 50.0);

    score
}

