        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let poor_fit = if fit_ratio < 0.5 { (0.5 - fit_ratio) * 80.0 } else { 0.0 };
        let early = (1.0 - step_index as f64 / total_items.max(1) as f64) * 10.0;
