    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
