    }

    // Continuous dead-space gradient — smooth waste curve on slack (refined slope).
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.12 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
