        }
    }

    // Residual homogenization pull — target post-residual near mean (widened band).
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 10.0 {
            score -= 3.0 * (1.0 - dist / 10.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — two-step lookahead on mid-range leftovers.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
