        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 25): variance-crush coupling — when fleet residuals are
    // dispersed, strongly prefer bins whose post-residual lands near the mean,
    // shrinking dead-space variance across the fleet.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dispersion = (mean_residual - (mean_residual * 0.5)).max(0.0); // proxy: scale of spread
