        if dispersion >= 0.0 && dist > 10.0 && open_bins_count > 2 {
            score += 0.08 * dist.min(40.0) * (open_bins_count as f64).ln().max(1.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 25): mid-slack triage — for slack in 11..=20, penalize
    // proportionally to how far it sits from the reusable band edge, closing
    // the gap the pair-fit term leaves open.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = (post_residual - next_item_size) as f64;
        if after > 10.0 && after <= 20.0 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 1.5 + 0.25 * (after - 10.0) * (1.0 - progress);
            }
        }
    }

    // MUTATION (gen 25): late-stream exact-retirement bonus — as the stream
    // ends, prioritize placements that fully consume a bin to cut tail waste.
    if progress > 0.75 && post_residual == 0 && bin_residual < bin_capacity {
        score -= 10.0 * (progress - 0.75) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: mod-10 residue classes ---
    let pr = post_residual;
    let pr_class = pr % 10;
    // Residues near 0 (tiny slivers) are dead space -> penalize via non-linear bump
    let sliver = ((10 - pr_class).min(pr_class)) as f64;
    score += 6.0 * (1.0 - sliver / 5.0); // residue 0 -> reward, residue 5 -> neutral

    // Perfect-fill reward (post_residual == 0)
    if pr == 0 {
        score -= 30.0;
    }

    // Integer-division threshold bands on post_residual: capacity fractions
    let cap = bin_capacity as f64;
    let pr_frac = pr as f64 / cap;
    if pr_frac < 0.10 {
        score += 8.0; // unusable dead space
    } else if pr_frac < 0.25 {
        score += 3.0;
    } else if pr_frac > 0.5 {
        score -= 4.0; // roomy bin, plenty for future items
    }

    // Harmonic coupling with next item: does post_residual accommodate it?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // reward proportional to tightness of the fit for the next item
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            // bonus if next item's harmonic class (decade) matches post_residual decade
            if pr / 10 == next_item_size / 10 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to how close it was
            let gap = (next_item_size - pr) as f64;
            score += 4.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish score; open a new bin only if no good fit exists
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * mean_residual + (open_bins_count as f64);
        // late in stream, slightly discourage proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for tight fits generally
    score += 0.1 * item_size as f64;

    score
}

