            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // MUTATION: residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 13): pair-fit anticipation.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // MUTATION (gen 13): scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 25): perfect-decomposition lookahead — if the post-residual
    // can be exactly split as next + item_size (a natural pair completion),
    // reward strongly; this couples fine-grained residual fitting with
    // two-step lookahead to retire bins early.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after == item_size {
            score -= 10.0 * (1.0 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 25): dead-space ratio gradient — continuous penalty on
    // unusable leftover fraction relative to mean residual, replacing the
    // hard slack>45 jump with a smooth curve tied to fleet absorbability.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let dead_frac = slack / cap;
        if dead_frac > 0.05 && slack > mean_residual * 1.5 {
            score += 8.0 * (dead_frac - 0.05) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 25): scarcity-driven tightest-bin magnet — when few bins
    // fit, amplify the preference for the smallest post-residual so load
    // concentrates instead of spreading across the fleet.
    if fitting_bins_count <= 3 && bin_residual < bin_capacity && post_residual > 0 {
        score += (4.0 - fitting_bins_count as f64) * 1.5 * (post_residual as f64 / cap) * (1.0 - progress);
    }

    // MUTATION (gen 25): new-bin gate tightening — refuse a fresh bin when the
    // collective residual space of open bins can still hold the item and the
    // next item, unless the item is large enough to justify isolation.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let collective = mean_residual * open_bins_count as f64;
        let need = item_size as f64 + next_item_size as f64;
        if collective >= need && item_size < 70 {
            score += 6.0 + 0.05 * (collective - need);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic + cubic shaping on fill fraction after placement.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness - 20.0 * tightness * tightness * tightness;

    // Dead-space waste: penalize leftovers too small for typical items.
    if post_residual > 0 && post_residual < 20 && next_item_size != post_residual {
        let scarcity = 1.0 + 0.5 / (fitting_bins_count as f64).max(1.0);
        score += (25.0 + (20 - post_residual) as f64) * scarcity;
    }

    // Lookahead: exact chain fit is a jackpot, amplified by scarcity.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0 + 10.0 / (fitting_bins_count as f64).max(1.0);
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 8.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 35.0;
        }
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next > 0 && after_next <= 12 {
            score -= 12.0;
        }
    }

    // Last-chance bin: only fitting bin gets strong preference.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Consolidation pressure: prefer fuller bins, scaled with open-bin count.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Residual-deviation coupling: favor bins tighter than mean, with kick.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;
    if dev > 20.0 {
        score -= 6.0;
    }

    // Progress-scaled selectivity: early = picky, late = greedy.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin decision: base penalty grows with open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64);
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
        if progress > 0.6 && mean_residual < 25.0 {
            score -= 8.0 * progress;
        }
        let fill = item_size as f64 / cap;
        if fill > 0.8 {
            score -= 18.0 * (fill - 0.8) * 5.0;
        }
        if item_size <= 10 && open_bins_count > 0 {
            score += 40.0;
        }
        if fitting_bins_count > 2 {
            score += 5.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Fresh-bin lookahead: only open if leftover can chain the next item.
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if item_size >= 20 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // Waste-anticipation for the fresh-bin candidate.
        if next_item_size > 0 {
            let pr = post_residual as i64;
            let ni = next_item_size as i64;
            let leftover = pr - ni;
            if leftover == 0 {
                score -= 9.0;
            } else if leftover < 0 {
                let stranded = (-leftover) as f64;
                if stranded < 8 {
                    score += 4.0 + 0.5 * stranded;
                } else {
                    score -= 2.0;
                }
            } else {
                let sliver = leftover as f64;
                if sliver < mean_residual {
                    score += 3.0 + 0.15 * sliver * (1.0 + progress);
                }
            }
        }
        if mean_residual * (open_bins_count as f64) >= next_item_size as f64 && item_size < next_item_size {
            score += 8.0;
        }
    }

    // Dual-fit shaping: prefer bins whose post-residual is closest to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * ((next_item_size - post_residual) as f64 / cap) * (fitting_bins_count as f64);
    }

    // Near-exact fit bonus.
    if post_residual > 0 && post_residual <= 2 {
        score -= 20.0;
    }

    // Dead-space ratio shaping — steer toward dual/triple fits.
    if post_residual > 0 && next_item_size > 0 {
        let strand = (post_residual as f64 / cap) * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        if post_residual < next_item_size {
            score += 18.0 * strand;
        } else {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 14.0;
            } else if slack > 45 {
                score += 6.0;
            }
        }
    }

    // Scarcity-aware consolidation — sharpen preference for the tightest bin.
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / cap);
    }

    // Residual-band matching: reward post-residuals in the reusable band.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * progress;
        if (slack as f64) <= band {
            score -= 6.0 * (1.0 + 0.5 * progress);
        } else {
            score += (0.06 + 0.04 * (1.0 - progress)) * ((slack as f64) - band);
        }
    }

    // Variance-aware tightness: homogenize dispersed residuals.
    if mean_residual > 30.0 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }

    // Capacity-scaled waste anticipation.
    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
            }
        }
    }

    // Exact-sweep reward: clean bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Fleet-fit conservation — protect roomy residuals for large next items.
    if next_item_size > 0 && next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — two-step lookahead reward (gen 13, reinforced).
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.5 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 26): dead-space ratio gradient — continuous penalty on the
    // fraction of the bin that will be stranded after placing the next item.
    // Targets diagnosed weakness: suboptimal residual / dead space ratio.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let stranded = (post_residual - next_item_size) as f64 / cap;
        score += 55.0 * stranded * stranded * (0.6 + 0.4 * (1.0 - progress));
        // But if the stranded space is small enough to be absorbed by the
        // fleet's collective residual, soften the penalty.
        let collective = mean_residual * (open_bins_count as f64).max(1.0);
        if collective > (post_residual - next_item_size) as f64 {
            score -= 12.0 * (1.0 - ((post_residual - next_item_size) as f64 / collective).min(1.0));
        }
    }

    // MUTATION (gen 26): fragmentation guard — when the current residual leaves
    // a fragment after this fit that no plausible next item could use (fragment
    // below the smallest useful band), penalize proportionally to open bins.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let frag = post_residual - next_item_size;
        if frag < 12 && frag > 4 {
            score += 1.5 * (frag as f64) * (open_bins_count as f64).ln().max(1.0) * 0.4;
        }
    }

    // MUTATION (gen 26): two-item lookahead sum — when post-residual can host
    // the next item plus a plausible follow-up (next + small), reward the
    // bin for being on a clean retirement path.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 11 && after <= 30 {
            // mid-range leftover: mild penalty unless fleet residual is thin
            let fleet_thin = mean_residual < 12.0;
            if !fleet_thin {
                score += 0.08 * (after as f64) * (1.0 - progress);
            } else {
                score -= 3.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the virtual new-bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tight-fit reward: strongly prefer bins whose residual is consumed almost exactly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 90.0 * fit_ratio * fit_ratio; // quadratic bonus, peaks at perfect fit

    // Penalize dead space: small post-residuals are good, but residual < 10 is truly dead.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance pressure: if only this bin fits, prefer it heavily to avoid a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 55.0;
    }

    // Lookahead coupling: reward leaving a gap that the next item can fill.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if gap >= next_item_size as f64 {
            score -= 20.0 * (1.0 - ((gap - next_item_size as f64) / bin_capacity as f64).min(1.0));
        } else {
            score += 8.0; // gap too small for the upcoming item
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, closure matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> discourage opening new bins,
    // encourage packing into laggard bins.
    if is_new_bin {
        let crowding = open_bins_count as f64;
        let slack = mean_residual / bin_capacity as f64;
        score += 30.0 + 10.0 * slack + 0.5 * crowding.sqrt();
        // Allow a new bin when the item is huge relative to typical gaps.
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
    } else {
        // Favor bins that are below-average residual (denser bins) to consolidate.
        score += 6.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
