    }

    // Last-chance bin: only fitting bin gets strong preference.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Consolidation pressure scaled with open-bin count.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Perfect closure bonus: clean bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 40.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Near-perfect residual sliver.
    if post_residual > 0 && post_residual <= 2 {
        score -= 20.0;
    }

    // Scarcity gate: sharpen preference when only one or two bins fit.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
