    if next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // New empty bin candidate: strongly discourage unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64) + (fitting_bins_count as f64) * 2.0;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
        if progress > 0.6 && mean_residual < 25.0 {
            score -= 8.0 * progress;
        }
        let fill = item_size as f64 / cap;
        if fill > 0.8 {
            score -= 18.0 * (fill - 0.8) * 5.0;
        }
