            score += 40.0;
        }
        // Fresh-bin lookahead: only open if leftover can chain the next item.
        if next_item_size > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
    }

