    // Early: mild penalty (keep bins open, flexible). Late: strong penalty (tighten packing).
    let mut score = pr * (1.0 + 2.0 * progress * progress);

    // Smooth interaction: reward small post-residual quadratically.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.5 * (0.5 + progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr.max(1.0);
            score -= 12.0 * fit_ratio * (1.0 - fit_ratio) * (0.3 + progress);
        } else {
            // Smooth penalty when next item won't fit: proportional overshoot.
            score += 6.0 * ((nxt - pr) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong smooth reward to use it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr * norm_pr);
    }

    // Prefer bins with residual below mean when tight packing (smooth mean-deviation term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * progress - 2.0 * dev * (1.0 - progress);

    // Mild penalty for proliferating bins late in the stream.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
