        score -= 500.0;
    }

    // Prefer bins tighter than the mean (best-fit bias relative to mean_residual)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream: consolidate harder, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 120.0 + 300.0 * progress;
        if fitting_bins_count > 0 {
            // an open bin can already fit: strongly discourage new bin
            score += 250.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
