        if gap >= 1.0 && gap <= 4.0 {
            score -= (3.0 + 2.0 * (4.0 - gap)) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        } else if gap > 4.0 && gap <= 10.0 {
            score -= 4.0 * (1.0 - gap / 10.0) * (1.0 + progress);
