    let dev = mean_residual - bin_residual as f64;
    score -= (bin_residual as f64 - mean_residual) * 0.3;
    if dev > 20.0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 40.0 + 8.0 + 6.0 * progress;
    }

    // Tightness shaping: quadratic + cubic on fill fraction.
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 30.0 * tightness * tightness - 20.0 * tightness * tightness * tightness;

    // Small unusable sliver penalty.
    if post_residual > 0 && post_residual < 20 && next_item_size != post_residual {
        let scarcity = 1.0 + 0.5 / (fitting_bins_count as f64).max(1.0);
        score += (25.0 + (20 - post_residual) as f64) * scarcity;
    }

    // Consolidation pressure: prefer fuller bins, scaled with open-bin count.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Progress-scaled selectivity: early = picky, late = greedy.
    score *= 1.0 + 0.3 * (1.0 - progress);

