        }
    }

    // MUTATION: scarcity-weighted exact-fit gate for 1-2 fitting bins.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual more aggressively for near-full bins.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; slight penalty proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progression.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 20.0 * progress;
        // If existing bins are fragmented (high mean residual spread), new bin more attractive.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 0.1 * fragmentation;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual deviates below the mean (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    let bin_pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += 0.5 * bin_pressure;

    // Reward filling bins proportionally to item size (big items in tight bins).
    score -= 0.1 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

