    // MUTATION (gen 28): fragmentation sweep — when the fleet's collective
    // residual is large but fragmented across many bins, reward candidates
    // that consolidate rather than open new capacity, scaled by scarcity.
    if bin_residual < bin_capacity && open_bins_count >= 4 {
        let collective = mean_residual * open_bins_count as f64;
