    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size && (post_residual as f64) < 10.0 + 0.3 * mean_residual {
            score += 18.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit_norm = pr / 100.0;

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // later in the stream, dead space becomes more costly
    let progress_penalty = 40.0 * progress * pr_norm * pr_norm * (1.0 - pr_norm);
    score += progress_penalty;

    // Reward tight fits (post_residual near zero) via smooth term
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 30.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize opening new bins early / when fitting bins exist
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 25.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Lookahead: smooth reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let slack = ((pr - nxt) / cap).max(0.0);
        score -= fits_next * 18.0 * (1.0 - slack * slack);
        // penalize post-residuals that are too small for typical next items
        score += 10.0 * (1.0 - fits_next) * pr_norm;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

