            score += 10.0 * dead_ratio * dead_ratio * (0.4 + 0.6 * (1.0 - progress));
            if !absorbable {
                // No other bin can take next item: tolerate the strand.
                score -= 5.0 * dead_ratio;
            }
        } else {
            // Usable leftover: reward proportionally to how well it matches
            // the next item, sharpened by scarcity of fitting bins.
            let match_q = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 5.0 * match_q * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0)) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 28): two-step chain bonus — if the post-residual can
    // exactly absorb next_item plus a plausible small follow-up (5..=15),
    // reward with a smooth curve; encourages bin retirement via paired loads.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 11 && after <= 15 {
            score -= 3.0 * (1.0 - (after - 11) as f64 / 4.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 28): new-bin gate refinement — when opening a fresh bin,
    // penalize more strongly if the item is small relative to the largest
    // open-bin residual that could hold it, and only relax the gate when
    // the fresh bin's leftover would be a clean chain for the next item.
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 {
        let leftover = post_residual as i64 - next_item_size as i64;
        if leftover >= 0 && leftover <= 6 {
            score -= 8.0 * (1.0 - leftover as f64 / 6.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: hard reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residue modulo capacity quarters.
    let quarter = bin_capacity / 4;
    let post_mod = post_residual % bin_capacity;
    let class = post_mod / quarter; // 0..3 harmonic class of leftover

    // Penalize dead space in the lowest classes (tiny unusable leftovers),
    // reward mid classes that can absorb typical next items.
    match class {
        0 => score += 60.0 * (1.0 - (post_mod as f64) / (quarter as f64)),
        1 => score -= 15.0,
        2 => score -= 10.0,
        _ => score += 5.0,
    }

    // Coupling with lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match: next item divides leftover nicely.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 25.0;
            } else {
                score -= 12.0;
            }
        } else {
            // Next item cannot follow here -> leftover likely dead.
            score += 0.35 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced late in the stream or when
        // open bins are crowded (high mean fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fill = 1.0 - (mean_residual / cap);
        let penalty = 90.0 - 40.0 * progress - 30.0 * mean_fill;
        // If leftover class of the hypothetical placement is terrible,
        // opening fresh is relatively better.
        score = score.max(0.0) + penalty;
    }

    // Mild tie-break: prefer fuller bins (smaller residual) overall.
    score += 0.05 * (bin_residual as f64);

    score
}

