    // Continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
