    // MUTATION (gen 28): two-step dead-space projection — estimate whether the
    // residual after the next item is likely to strand waste given the fleet's
    // absorbable pool; penalize stranded slivers, reward clean retirements.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = (post_residual - next_item_size) as f64;
        let pool = (mean_residual * open_bins_count as f64).max(1.0);
        let strand_risk = if after < 12.0 {
            // Small leftovers are hard to reuse unless pool is tiny.
            let absorb = (pool / (pool + after * after)).max(0.0);
            1.0 - absorb
        } else {
            0.0
        };
        score += 9.0 * strand_risk * (after / 12.0) * (0.4 + 0.6 * (1.0 - progress));
        // Complementary reward when the leftover is likely absorbed by the fleet.
        if after >= 3.0 && after < 12.0 && pool > after {
            score -= 3.0 * (1.0 - after / 12.0) * (1.0 + 0.5 * progress);
        }
    }

    // MUTATION (gen 28): waste-budget-aware new-bin gate — open a fresh bin only
    // when the item would strand more dead space in any existing bin than the
    // fresh bin's own projected waste; scaled by remaining stream length.
    if bin_residual == bin_capacity {
        let remaining = if total_items > step_index { (total_items - step_index) as f64 } else { 1.0 };
        let stream_factor = (1.0 - (remaining / (total_items.max(1) as f64).max(1.0)).min(1.0)).max(0.0);
        let projected_fresh_waste = (cap - item_size as f64).max(0.0);
        let worst_existing_waste = if fitting_bins_count > 0 {
            (next_item_size as f64).min(cap) * 0.3
        } else {
            projected_fresh_waste
        };
        if projected_fresh_waste > worst_existing_waste && stream_factor > 0.3 {
            score += 6.0 * (projected_fresh_waste - worst_existing_waste) / cap * (1.0 - stream_factor);
        }
        // Late-stream consolidation: fewer open bins is better near the end.
        if stream_factor > 0.7 {
            score -= 3.0 * stream_factor * (open_bins_count as f64).ln().max(0.0);
        }
    }

    score
}

