            score += (0.06 + 0.04 * (1.0 - progress)) * ((slack as f64) - band);
        }
    }

    // Variance-aware tightness: homogenize dispersed residuals.
    if mean_residual > 30.0 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }

    // Capacity-scaled waste anticipation.
    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
            }
        }
    }

    // Exact-sweep reward: clean bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Fleet-fit conservation — protect roomy residuals for large next items.
    if next_item_size > 0 && next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack (reinforced).
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.13 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — two-step lookahead toward bin retirement.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 28): dead-space liquidity index — a leftover is only "wasted"
    // if no other open bin can absorb it; scale the slack penalty by the chance
    // the pool of open residuals covers the stranded space, avoiding over-
    // penalizing slack that the fleet would use anyway.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 10.0 {
            let pool = (mean_residual * open_bins_count as f64).max(1.0);
            let liquidity = (pool / (slack * open_bins_count as f64).max(1.0)).min(1.0);
            score += 5.0 * slack * (1.0 - liquidity) / cap * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 28): fragmentation-aware new-bin gate — opening a bin when
    // the fleet's aggregate residual already exceeds the item is a cardinal sin;
    // make the penalty proportional to how much aggregate space is being ignored.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let aggregate = mean_residual * open_bins_count as f64;
        let excess = aggregate - item_size as f64;
        if excess > 0.0 {
            score += 0.25 * excess.min(120.0) * (1.0 - 0.4 * progress);
        }
        // But reward opening when the item is huge relative to everything open.
        if item_size as f64 > aggregate {
            score -= 14.0;
        }
    }

    // MUTATION (gen 28): mid-band residual preservation — leftovers in the
    // 15..=35 range are the most reusable for unknown-distribution streams;
    // gently favor bins that land there after placement.
    if post_residual >= 15 && post_residual <= 35 && bin_residual < bin_capacity {
        let center_pull = 1.0 - ((post_residual as f64 - 25.0).abs() / 10.0);
        score -= 3.0 * center_pull.max(0.0) * (0.5 + 0.5 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let x = r / c;
    let nr = next_item_size as f64;
    let fbc = (fitting_bins_count as f64).max(1.0);

    // Base: prefer tight fits with non-linear dead-space penalty
    let mut score = x * x * (1.0 + 2.0 * t) * c;
    let coupling = (x - 0.5) * (x - 0.5) * (1.0 + 12.0 * t * (1.0 - t));
    score += coupling * c * 0.5;

    // Last-chance bin: strong preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * t;
    }

    // Mean-residual consolidation
    score += 0.12 * (mean_residual - r);

    // Lookahead: reward bins whose post-residual chains the next item well
    if next_item_size > 0 {
        if r >= nr {
            let slack = r - nr;
            if next_item_size == post_residual {
                score -= 60.0 + 10.0 / fbc;
            } else if slack <= 4 {
                score -= 30.0 - 4.0 * slack;
            } else if slack <= 12 {
                score -= 10.0 * (1.0 - slack / 12.0);
            } else {
                score += 0.08 * (slack - 12.0).min(60.0) * (0.6 + 0.4 * (1.0 - t));
            }
        } else {
            let dead = nr - r;
            if dead < 20 {
                score += (10.0 + 0.8 * dead) / fbc;
            } else {
                score += 8.0;
            }
        }
    }

    // Scattering pressure: prefer filling existing bins late
    score += t * open_bins_count as f64 * 0.3;

    // Fill-ratio consolidation
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 8.0;

    // Clean retirement reward
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 10.0 + 6.0 * t;
    }

    // Tiny sliver penalty: leftover too small to reuse is waste
    if post_residual > 0 && post_residual < 8 && next_item_size != post_residual {
        score += 15.0 + (8 - post_residual) as f64;
    }

    // New-bin candidate: penalize unless opening is genuinely better
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - t) + 1.5 * open_bins_count as f64;
        // Open a fresh bin when remaining open space can't absorb the next item
        let pool = mean_residual * open_bins_count as f64;
        if next_item_size > 0 && pool < nr * 1.2 {
            score -= 18.0;
        }
        if item_size <= 10 && open_bins_count > 0 {
            score += 35.0;
        }
        if fitting_bins_count > 2 {
            score += 4.0 * (fitting_bins_count as f64 - 2.0);
        }
        if next_item_size > 0 && post_residual >= next_item_size as u32 {
            score -= 6.0;
        }
    }

    // Homogenization pull: target post-residual near mean residual
    if post_residual > 0 && next_item_size > 0 && r >= nr {
        let dist = (r - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - t);
        }
    }

    // Protect roomy residuals for large upcoming items
    if next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        if r >= nr {
            score -= 4.0 * (1.0 - t) * x;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless current bin residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 45.0;

        // If the next item fits perfectly after this one in a fresh bin, encourage it.
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0;
            } else {
                score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        }

        // Encourage new bin when this bin is the only fitting option for a tight stream.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }

        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;

        // If mean residual is large (plenty of slack), discourage new bins.
        score += 0.3 * mean_residual;

        return score;
    }

    // ---- 2-step lookahead: reward when next_item_size fits into post_residual ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Strong reward for a perfect 2-item match (both items exactly fill the bin).
            if gap == 0.0 {
                score -= 55.0;
            } else {
                // Reward proportional to how tight the 2-item fit is.
                score -= 35.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow here: mild penalty scaled by overflow amount.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.25 * overflow;
        }
    } else {
        // Last item: just minimize residual (already the base score).
    }

    // Penalize dead space that nothing (size >= 1) can plausibly use relative to mean residual.
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for using bins with smaller original residual (tighter bins first).
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
