    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let fleet = mean_residual * (open_bins_count as f64).max(1.0);
        if fleet > slack && slack > 20.0 {
            score += 0.08 * (slack - 20.0) * (1.0 - (slack / fleet).min(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
