    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 30.0; // chainable placement
            if post_residual == next_item_size as u32 {
                score -= 25.0; // perfect chain
            }
        } else if post_residual > 0 && (next_item_size as u32) > post_residual {
            // leftover too small for next item: penalize more late in stream
            score += 10.0 + 15.0 * t;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // when many bins fit, prefer the tightest; base post_residual already does this
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New empty bin candidate: only attractive when current fit is poor
    // or the bin pool is fragmented / mean residual is bloated.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0;
        let fragmentation = mean_residual > 45.0 && open_bins_count > 3;
        if poor_fit || fragmentation || t < 0.15 {
            score -= 35.0 + 30.0 * (1.0 - t);
        } else {
            score += 50.0; // discourage wasteful new bins mid/late stream
        }
    }

    // Prefer filling bins that are already well-utilized.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill;

    // Slight nudge toward bins below mean residual (balance avoidance of stranded space).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
