    // residual fitting with lookahead by rewarding bins whose post-residual
    // is a near-divisor of the next item (multi-item chain potential).
    if next_item_size > 1 && post_residual > 0 && post_residual < next_item_size {
        let rem = next_item_size % post_residual.max(1);
        if rem <= 2 {
            let chains = (next_item_size / post_residual.max(1)) as f64;
            score -= 3.0 * (chains - 1.0).min(3.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 29): slack-deficit gradient — when the item cannot fully
    // consume the residual, penalize proportionally to the unusable gap,
    // damped by how much slack the rest of the fleet still holds.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let fleet_slack = (mean_residual * (open_bins_count as f64).max(1.0)).max(1.0);
        let relief = (gap / fleet_slack).min(1.0);
        if gap > 12.0 {
            score += 0.08 * (gap - 12.0) * (0.3 + 0.7 * relief) * (1.0 - 0.5 * progress);
        }
    }

    // MUTATION (gen 29): late-stream consolidation kick — near the end of the
    // stream, strongly prefer bins that can absorb the next item as well,
    // since fewer chances remain to fix dead space.
    if progress > 0.75 && next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        score -= 5.0 * (progress - 0.75) * 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post-residual), with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream -> value compactness more
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Dead-space penalty: residuals too small to fit typical future items
    let dead_threshold = 0.15 * cap;
    if pr < dead_threshold {
        score += 8.0 * (dead_threshold - pr) / cap;
    }

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = 1.0 / (1.0 + gap / cap);
        score -= 6.0 * fit_kernel * fit_kernel;
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // New-bin candidate: encourage opening a fresh bin early or when fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = norm_pr; // = 1.0 for empty bin, larger pr elsewhere
        score -= 4.0 * (1.0 - progress) + 3.0 * (1.0 - poor_fit);
    }

    score
}

