            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // MUTATION: continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION: near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // MUTATION: residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // MUTATION (gen 13): pair-fit anticipation.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // MUTATION (gen 13): scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 21): two-step dead-space sweep.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = (post_residual - next_item_size) as f64;
        if after > 10.0 && after < 40.0 {
            let harvest = (item_size as f64) / after.max(1.0);
            if harvest > 0.5 {
                score -= 5.0 * (harvest - 0.5) * (1.0 - progress);
            }
        }
    }

    // MUTATION (gen 21): fragmented-fleet gate.
    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
        let pressure = if fitting_bins_count >= 4 { 1.5 } else { 0.5 };
        score += pressure * (12 - post_residual) as f64 * (0.4 + 0.6 * (1.0 - progress));
    }

    // MUTATION (gen 21): mean-anchored slack matching.
    if post_residual >= next_item_size && next_item_size > 0 && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        let corridor = (mean_residual - slack).abs();
        if corridor < 5.0 {
            score -= 3.0 * (1.0 - corridor / 5.0) / (fitting_bins_count as f64).max(1.0).sqrt();
        }
    }

    // MUTATION (gen 29): dead-space ratio gate — penalize bins whose leftover
    // fraction exceeds what the item actually consumed, scaled by progress.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
        if waste_ratio > 0.6 {
            score += 8.0 * (waste_ratio - 0.6) * (0.5 + progress);
        } else if waste_ratio < 0.25 {
            score -= 5.0 * (0.25 - waste_ratio) * (1.0 + progress);
        }
    }

    // MUTATION (gen 29): exact-fill anticipation — reward bins where item +
    // next item together leave nothing, combining fine fit with lookahead.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size {
        let combined = bin_residual - item_size - next_item_size;
        if combined == 0 {
            score -= 30.0;
        } else if combined <= 6 {
            score -= 12.0 * (1.0 - combined as f64 / 7.0);
        }
    }

    // MUTATION (gen 29): residual pool pressure — when the fleet's total slack
    // is tight, avoid opening bins for small items; when slack is ample,
    // tolerate opening to preserve large residuals for large items.
    let pool = mean_residual * open_bins_count as f64;
    if next_item_size > 0 && bin_residual < bin_capacity {
        let slack = post_residual as f64;
        if slack >= next_item_size as f64 && pool < next_item_size as f64 * 1.5 {
            score -= 4.0;
        }
        if slack < next_item_size as f64 && pool > next_item_size as f64 * 3.0 {
            score += 3.0 * (1.0 - slack / next_item_size.max(1) as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
