    // MUTATION (gen 13): pair-fit anticipation — when the next item plus a
    // known small follow-up would exactly retire the bin, reward strongly;
    // combines fine-grained residual fitting with two-step lookahead.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
