    // MUTATION (gen 30): two-step chain retirement — reward placements whose
    // post-residual exactly matches the next item (bin retires next step),
    // weighted by how crowded the fleet is; discourages opening fresh bins
    // when a chainable bin exists.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual < bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln().max(1.0) * (0.5 + progress);
    }

    // MUTATION (gen 30): dead-space gradient sharpening — when the leftover
    // after the next item is stranded (too small for the mean residual),
    // penalize proportionally to the wasted fraction; pushes selection toward
    // bins whose remainder stays reusable.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = (post_residual - next_item_size) as f64;
        if after > 10.0 && after < mean_residual {
