    }

    // MUTATION (gen 30): new-bin gate tightening — refuse a fresh bin when
    // some open bin can hold the item AND the fleet's collective slack can
    // absorb the next item; only allow opening when slack is truly fragmented.
    if bin_residual == bin_capacity && next_item_size > 0 && open_bins_count > 0 {
        let collective = mean_residual * open_bins_count as f64;
        if collective >= (item_size + next_item_size) as f64 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 30): large-item anchoring — when the item consumes most of
    // the bin residual, prefer it strongly to avoid leaving awkward mid-range
