    if bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual.max(1) as f64;
        if consumed > 0.7 {
            score -= 3.0 * (consumed - 0.7) * 10.0 * (1.0 - progress);
        }
    }

    score
}

