    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity / 10).
    let class = post_residual % 10;
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 100.0; // unusable sliver: heavy penalty
    } else {
        // reward post-residuals that are "harmonic" sizes (multiples of 5 or 10)
        if class == 0 {
            score -= 12.0;
        } else if class == 5 {
            score -= 6.0;
        } else {
            score += (10 - class) as f64 * 0.5;
        }
    }

