    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap % 10 == 0 {
            score -= 10.0;
        } else if gap < 10 {
            score += 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: mild penalty proportional to waste
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual < 20 {
            score -= 5.0; // opening fresh bin for big item is fine
        }
    }

    // Prefer filling tighter bins when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 0.3;

    // Stream progression: become greedier (tighter fits) late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * (1.0 - progress);

    score
}

