    // Dead-space ratio shaping — steer toward dual/triple fits.
    if post_residual > 0 && next_item_size > 0 {
        let strand = (post_residual as f64 / cap) * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        if post_residual < next_item_size {
            score += 18.0 * strand;
        } else {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 14.0;
            } else if slack > 45 {
                score += 6.0;
            }
        }
    }

    // Scarcity-aware consolidation — sharpen preference for the tightest bin.
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / cap);
    }

    // Residual-band matching: reward post-residuals in the reusable band.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * progress;
        if (slack as f64) <= band {
            score -= 6.0 * (1.0 + 0.5 * progress);
        } else {
            score += (0.06 + 0.04 * (1.0 - progress)) * ((slack as f64) - band);
        }
    }

    // Variance-aware tightness: homogenize dispersed residuals.
    if mean_residual > 30.0 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }

    // Capacity-scaled waste anticipation.
    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
            }
        }
    }

    // Exact-sweep reward: clean bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Fleet-fit conservation — protect roomy residuals for large next items.
    if next_item_size > 0 && next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — next item plus a small follow-up retires the bin.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 30): dead-space ratio gradient — penalize bins whose
    // post-residual is neither retireable nor chainable, scaled by how much
    // of the bin's original capacity ends up stranded. Smooth quadratic ramp
    // avoids cliff effects that the band/gradient terms only partially cover.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        let stranded_frac = stranded / cap;
        if stranded > 18.0 {
            // Large stranded gap: strong pull toward other bins unless
            // the collective residual pool can absorb the next item anyway.
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            let relief = if collective >= next_item_size as f64 { 0.5 } else { 1.0 };
            score += 10.0 * stranded_frac * stranded_frac * 100.0 * relief * (0.4 + 0.6 * progress);
        } else if stranded <= 6.0 {
            // Small gap: mild penalty, another small item may still land.
            score += 1.5 * stranded_frac * 100.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 30): triple-fit lookahead — when the post-residual can
    // host the next item AND the remainder after that is still above the
    // typical small-item floor, reward the compaction chain explicitly.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 11 && after <= 20 && mean_residual < after as f64 {
            score -= 3.0 * (1.0 - progress) * (1.0 - (after as f64 - 11.0) / 9.0);
        }
    }

    // MUTATION (gen 30): new-bin gate refinement — refuse fresh bins when
    // the item is small and any open bin's residual exceeds it by a wide
    // margin, but allow when the fleet is nearly saturated.
    if bin_residual == bin_capacity && item_size <= 25 && open_bins_count > 0 {
        let saturation = mean_residual * (open_bins_count as f64) / (cap * open_bins_count as f64);
        if mean_residual > item_size as f64 + 5.0 && saturation < 0.75 {
            score += 18.0 * (1.0 - saturation);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item.
        score += 6.0;
    }

    // Open-bins pressure: penalize opening/using bins when many are open,
    // favor consolidation; but last-chance bins get a reward.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins already fit.
        score += 15.0 + (fitting_bins_count as f64) * 10.0;
        // Early in stream, opening new bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        if fitting_bins_count == 1 {
            // Last chance: strongly prefer using this bin.
            score -= 20.0;
        }
    }

    // Favor bins tighter than the mean residual (good packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let x = r / c; // normalized post residual

    // Base: prefer tight fits, smooth non-linear dead-space penalty
    let mut score = x * x * (1.0 + 2.0 * t) * c;

    // Polynomial coupling of post residual with stream progress
    let coupling = (x - 0.5) * (x - 0.5) * (1.0 + 3.0 * t * (1.0 - t) * 4.0);
    score += coupling * c * 0.5;

    // Reward last-chance bins (avoid opening new bins when only one fits)
    if fitting_bins_count == 1 {
        score -= 14.0 + 22.0 * t;
    }

    // Slight preference toward bins below mean residual
    score += 0.08 * (mean_residual - r);

    // Lookahead: reward chains; exact fit is a jackpot
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr == r {
            score -= 60.0 + 8.0 / (fitting_bins_count as f64).max(1.0);
        } else if nr <= r {
            let fit = 1.0 - (r - nr) / c;
            score -= 10.0 * fit * fit;
            let after = r - nr;
            if after <= 4.0 {
                score -= (3.0 + 2.0 * (4.0 - after)) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
            } else if after <= 10.0 {
                score -= 4.0 * (1.0 - after / 10.0) * (1.0 + t);
            }
        } else {
            score += 4.0 + 6.0 * ((nr - r) / c);
        }
    }

    // Late stream: discourage scattering; prefer filling existing bins
    score += t * open_bins_count as f64 * 0.3;

    // Exact-sweep reward: clean bin retirement
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * t;
    }

    // Near-exact fit bonus: tiny leftover slivers
    if post_residual > 0 && post_residual <= 2 {
        score -= 20.0;
    }

    // Dead-space waste: penalize leftovers too small for typical items
    if post_residual > 0 && post_residual < 20 && next_item_size != post_residual {
        let scarcity = 1.0 + 0.5 / (fitting_bins_count as f64).max(1.0);
        score += (25.0 + (20 - post_residual) as f64) * scarcity;
    }

    // Scarcity-aware consolidation: sharpen tightest-bin preference
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - x);
    }
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * x;
    }

    // Residual-band matching: reward post-residuals in the reusable band
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * t;
        if slack <= band {
            score -= 6.0 * (1.0 + 0.5 * t);
        } else {
            score += (0.06 + 0.04 * (1.0 - t)) * (slack - band);
        }
    }

    // Fleet-fit conservation: protect roomy residuals for large next items
    if next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        if r >= next_item_size as f64 {
            score -= 4.0 * (1.0 - t) * x;
        } else if r >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - t);
        }
    }

    // New-bin candidate: penalize so it only wins when fits are terrible,
    // but allow opening when the item is large and mean residual is too small.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - t);
        if item_size <= 10 && open_bins_count > 0 {
            score += 40.0;
        }
        if item_size as f64 >= 0.8 * c {
            score -= 18.0 * (item_size as f64 / c - 0.8) * 5.0;
        }
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if t > 0.8 {
            score += 10.0 * t;
        }
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item still fits in the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
    }
    // Penalize leaving a gap that the next item cannot use (dead space).
    else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Reward tight fits relative to the bin: small post residual is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Compare against mean residual: bins already below mean residual are better to fill.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fitting bins exist, unless the item
    // is large and fits alone (then a fresh bin is fine).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        if item_size <= bin_capacity / 2 {
            score += 15.0;
        }
    }

    // Late in the stream, prefer consolidating into fewest bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0 * (open_bins_count as f64).recip().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
