    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Residual-deviation coupling: favor bins tighter than mean.
    let dev = mean_residual - bin_residual as f64;
