        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if item_size >= 20 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
