        if next_item_size == post_residual {
            score -= 70.0 + 10.0 / (fitting_bins_count as f64).max(1.0);
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 8.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 35.0;
        }
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next > 0 && after_next <= 12 {
            score -= 12.0;
        }
    }

    // Last-chance bin: only fitting bin gets strong preference.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Consolidation pressure: prefer fuller bins, scaled with open-bin count.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Residual-deviation coupling: favor bins tighter than mean, with kick.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;
    if dev > 20.0 {
        score -= 6.0;
    }

    // Progress-scaled selectivity: early = picky, late = greedy.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin decision: base penalty grows with open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64);
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
        if progress > 0.6 && mean_residual < 25.0 {
            score -= 8.0 * progress;
        }
        let fill = item_size as f64 / cap;
        if fill > 0.8 {
            score -= 18.0 * (fill - 0.8) * 5.0;
        }
        if item_size <= 10 && open_bins_count > 0 {
            score += 40.0;
        }
        if fitting_bins_count > 2 {
            score += 5.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Fresh-bin lookahead: only open if leftover can chain the next item.
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if item_size >= 20 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // Waste-anticipation for the fresh-bin candidate.
        if next_item_size > 0 {
            let pr = post_residual as i64;
            let ni = next_item_size as i64;
            let leftover = pr - ni;
            if leftover == 0 {
                score -= 9.0;
            } else if leftover < 0 {
                let stranded = (-leftover) as f64;
                if stranded < 8 {
                    score += 4.0 + 0.5 * stranded;
                } else {
                    score -= 2.0;
                }
            } else {
                let sliver = leftover as f64;
                if sliver < mean_residual {
                    score += 3.0 + 0.15 * sliver * (1.0 + progress);
                }
            }
        }
        if mean_residual * (open_bins_count as f64) >= next_item_size as f64 && item_size < next_item_size {
            score += 8.0;
        }
    }

    // Dual-fit shaping: prefer bins whose post-residual is closest to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * ((next_item_size - post_residual) as f64 / cap) * (fitting_bins_count as f64);
    }

    // Near-exact fit bonus.
    if post_residual > 0 && post_residual <= 2 {
        score -= 20.0;
    }

    // Dead-space ratio shaping — steer toward dual/triple fits.
    if post_residual > 0 && next_item_size > 0 {
        let strand = (post_residual as f64 / cap) * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        if post_residual < next_item_size {
            score += 18.0 * strand;
        } else {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 14.0;
            } else if slack > 45 {
                score += 6.0;
            }
        }
    }

    // Scarcity-aware consolidation — sharpen preference for the tightest bin.
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / cap);
    }

    // Residual-band matching: reward post-residuals in the reusable band.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * progress;
        if (slack as f64) <= band {
            score -= 6.0 * (1.0 + 0.5 * progress);
        } else {
            score += (0.06 + 0.04 * (1.0 - progress)) * ((slack as f64) - band);
        }
    }

    // Variance-aware tightness: homogenize dispersed residuals.
    if mean_residual > 30.0 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }

    // Capacity-scaled waste anticipation.
    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
            }
        }
    }

    // Exact-sweep reward: clean bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Fleet-fit conservation — protect roomy residuals for large next items.
    if next_item_size > 0 && next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — when the next item plus a known small follow-up
    // would exactly retire the bin, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 31): two-step dead-space forecast — estimate whether the
    // residual left after placing the next item can still absorb a fraction of
    // the mean residual pool; bins that strand unusable space get penalized
    // proportionally, bins that stay harvestable get a bonus.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        let pool = (mean_residual * open_bins_count as f64).max(1.0);
        let harvestable = (after as f64 / pool).min(1.0);
        // Small stranded slivers that no future item can use.
        if after < 5 && after > 0 {
            score += 2.0 * (1.0 - after as f64 / 5.0) * (1.0 - harvestable);
        }
        // Mid-range residuals that remain useful relative to the fleet.
        if after >= 11 && after as f64 <= mean_residual * 1.5 {
            score -= 3.0 * (1.0 - progress) * harvestable;
        }
    }

    // MUTATION (gen 31): global waste-pressure rebalance — when total open
    // residual already exceeds the remaining demand trend, tighten the
    // new-bin gate further to force deeper packing into existing bins.
    if bin_residual == bin_capacity {
        let fleet_residual = mean_residual * open_bins_count as f64;
        let demand_proxy = next_item_size as f64 + 0.5 * mean_residual;
        if fleet_residual > demand_proxy * 1.2 {
            score += 6.0 * ((fleet_residual / demand_proxy) - 1.2).min(2.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared waste penalty (small residuals are valuable).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining),
    // penalize if post residual is too small for next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // Dead space relative to lookahead need.
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented / the item is large and fits badly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly when mean residual is high (open bins are roomy).
        score += 40.0 + 80.0 * fragmentation;
        // Late in the stream, prefer closing out open bins.
        score += 50.0 * progress;
        // Large items in fragmented state benefit from a fresh bin.
        if item_size > 50 && fragmentation < 0.4 {
            score -= 70.0;
        }
    }

    // Slight preference for fuller bins among open ones (residual below mean).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let x = r / c;

    // Base: prefer tight fits, smooth non-linear dead-space penalty
    let mut score = x * x * (1.0 + 2.0 * t) * c;

    // Polynomial coupling of post residual with stream progress
    let coupling = (x - 0.5) * (x - 0.5) * (1.0 + 3.0 * t * (1.0 - t) * 4.0);
    score += coupling * c * 0.5;

    // Reward last-chance bins
    if fitting_bins_count == 1 {
        score -= 12.0 + 20.0 * t;
    }

    // Slight preference toward bins below mean residual
    score += 0.05 * (mean_residual - r);

    // Lookahead: exact chain fit jackpot
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr == r {
            score -= 55.0 + 8.0 / (fitting_bins_count as f64).max(1.0);
        } else if nr <= r {
            let fit = 1.0 - (r - nr) / c;
            score -= 8.0 * fit * fit;
            let after = r - nr;
            if after >= 1.0 && after <= 4.0 {
                score -= 3.0 + 2.0 * (4.0 - after);
            } else if after >= 5.0 && after <= 10.0 {
                score -= 4.0 * (1.0 - after / 10.0) * (1.0 + t);
            }
        } else {
            score += 4.0 + 8.0 * ((nr - r) / 100.0);
        }
        // Dead-space waste: penalize leftovers too small for typical items
        if r > 0.0 && r < 20.0 && nr != r {
            let scarcity = 1.0 + 0.5 / (fitting_bins_count as f64).max(1.0);
            score += (25.0 + (20.0 - r)) * scarcity;
        }
        // Near-exact fit bonus
        if r > 0.0 && r <= 2.0 {
            score -= 20.0;
        }
    }

    // Late stream: discourage scattering
    score += t * open_bins_count as f64 * 0.3;

    // Consolidation pressure: prefer fuller bins, scaled with open-bin count
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 8.0;

    // Residual-band matching: reward post-residuals in the reusable band
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * t;
        if slack <= band {
