        }
    }

    // Exact-sweep reward: clean bin retirement
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * t;
    }

    // New-bin candidate: penalize so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - t);

        // Waste-pressure rebalance: tighten gate when fleet residual exceeds demand
        let fleet_residual = mean_residual * open_bins_count as f64;
        let demand_proxy = next_item_size as f64 + 0.5 * mean_residual;
        if fleet_residual > demand_proxy * 1.2 {
            score += 6.0 * ((fleet_residual / demand_proxy) - 1.2).min(2.0);
        }
        if mean_residual < 15.0 {
            score -= 15.0;
        }
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
        if item_size <= 10 && open_bins_count > 0 {
            score += 35.0;
        }
        if fitting_bins_count > 2 {
            score += 5.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Fresh-bin lookahead
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if t > 0.8 {
            score += 10.0 * t;
        }
    }

    // Two-step dead-space forecast
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        let pool = (mean_residual * open_bins_count as f64).max(1.0);
        let harvestable = (after as f64 / pool).min(1.0);
        if after < 5 {
            score += 2.0 * (1.0 - after as f64 / 5.0) * (1.0 - harvestable);
        }
        if after >= 11 && after as f64 <= mean_residual * 1.5 {
            score -= 3.0 * (1.0 - t) * harvestable;
        }
    }

    // Fleet-fit conservation — protect roomy residuals for large next items
    if next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        if r >= next_item_size as f64 {
            score -= 4.0 * (1.0 - t) * (r / c);
        } else if r >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - t);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
