        // Fresh-bin lookahead: only open if leftover can chain the next item.
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if item_size >= 20 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // Waste-anticipation for the fresh-bin candidate.
        if next_item_size > 0 {
            let pr = post_residual as i64;
            let ni = next_item_size as i64;
            let leftover = pr - ni;
            if leftover == 0 {
                score -= 9.0;
            } else if leftover < 0 {
                let stranded = (-leftover) as f64;
                if stranded < 8 {
                    score += 4.0 + 0.5 * stranded;
                } else {
                    score -= 2.0;
                }
            } else {
                let sliver = leftover as f64;
                if sliver < mean_residual {
                    score += 3.0 + 0.15 * sliver * (1.0 + progress);
                }
            }
        }
        if mean_residual * (open_bins_count as f64) >= next_item_size as f64 && item_size < next_item_size {
            score += 8.0;
        }
        // MUTATION (gen 33): fresh-bin deep-fill gate — when the current item
        // nearly fills a fresh bin, opening it is almost free (it packs tightly),
        // but a fresh bin opened for a small item amid a rich residual fleet
        // is strongly discouraged.
        let fleet_residual = mean_residual * open_bins_count as f64;
        if fill > 0.55 && fleet_residual > next_item_size as f64 {
            score -= 10.0 * (fill - 0.55) * (1.0 - progress);
        }
