    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // MUTATION (gen 35): variance-aware homogenization — when residuals are
    // dispersed, pull post-residuals toward the fleet mean so future items
    // of typical size keep fitting; scaled by scarcity of fitting bins.
    if next_item_size > 0 && post_residual > 0 && bin_residual < bin_capacity {
        let dist = (post_residual as f64 - mean_residual).abs();
        if dist < 10.0 && post_residual >= next_item_size {
