    if next_item_size >= 50 && bin_residual < bin_capacity && post_residual < next_item_size && item_size < 20 {
        score += 4.0 * (1.0 - progress) * (next_item_size as f64 - post_residual as f64) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    // A residual below the minimum item size (1) is impossible, but residuals
    // that are too small to host any typical future item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // risky narrow gap
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit: reward strongly
    }

    // Non-linear penalty on remaining slack: waste grows quadratically for
    // large leftovers that will likely never be filled.
    let slack_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * slack_frac * slack_frac;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize placements that leave
    // this bin nearly empty relative to the mean residual.
    if open_bins_count > 0 {
        let pressure = (open_bins_count as f64).ln() * 4.0;
        score += pressure * slack_frac;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and current bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
            -6.0
        } else {
            0.0
        };
        score = 55.0 + lookahead_bonus - (item_size as f64) * 0.3;
    } else {
