        }
        if after >= 11 && after as f64 <= mean_residual * 1.5 {
            score -= 3.0 * (1.0 - progress) * harvestable;
        }
    }

    // Global waste-pressure rebalance — when total open residual already
    // exceeds the remaining demand trend, tighten the new-bin gate further.
    if bin_residual == bin_capacity {
        let fleet_residual = mean_residual * open_bins_count as f64;
        let demand_proxy = next_item_size as f64 + 0.5 * mean_residual;
        if fleet_residual > demand_proxy * 1.2 {
            score += 6.0 * ((fleet_residual / demand_proxy) - 1.2).min(2.0);
        }
    }

    // MUTATION (gen 36): dead-space entropy term — bins whose post-residual
    // is neither exact-fit, chainable, nor near the fleet mean represent
    // high-entropy fragments; penalize proportionally to how far the
    // post-residual sits from ALL useful targets, scaled by remaining stream.
    if next_item_size > 0 && post_residual > 0 && bin_residual < bin_capacity {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let d_chain = (pr - ni).abs();
        let d_mean = (pr - mean_residual).abs();
        let d_small = (pr - (ni * 0.5)).abs();
        let min_dist = d_chain.min(d_mean).min(d_small);
        if min_dist > 12.0 {
            score += 0.12 * (min_dist - 12.0).min(30.0) * (0.5 + 0.5 * (1.0 - progress));
        } else if min_dist < 4.0 {
            score -= 3.0 * (1.0 - min_dist / 4.0);
        }
    }

    // MUTATION (gen 36): large-item priority reservation — when the next item
    // is large relative to capacity, existing bins that can host it now but
    // would be consumed by the current small item get a deferral penalty,
    // steering small items into tighter bins instead.
    if next_item_size > 0 && next_item_size >= 0.6 * cap && bin_residual < bin_capacity
        && post_residual < next_item_size && item_size < next_item_size {
        score += 5.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;
    // Quadratic dead-space penalty: small post-residuals are wasted space
    score -= 0.5 * cap * norm_post * (1.0 - norm_post);
    // Smooth progress coupling: later in stream, prefer tighter fits more strongly
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);
    // Penalty when post-residual is too small to be useful but nonzero
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = pr - next;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }
    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Mild preference against scattering across many bins when residuals are large
    score += 0.05 * (open_bins_count as f64) * norm_post;
    // Mean residual interaction: prefer bins deviating below mean residual (tighter)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;
    score
}

