pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not perfectly zero
    // residual of 0 wastes nothing; slight reward for exact fit.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // into the post_residual (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward scaled by how well next item fills the remaining space
        let chain_fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 + 20.0 * chain_fill;
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item can't use,
        // especially if the dead space is small (unusable sliver).
        let gap = post_residual as f64;
        if gap < next_item_size as f64 {
            score += (next_item_size as f64 - gap) * 0.5;
        }
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already more filled than average (below-mean residual).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are nearly full or the fit is terrible. The empty-bin call has
    // post_residual == bin_capacity; make it unattractive when decent fits exist.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Exception: if next item is large and no bin chains well,
        // a fresh bin is less bad (partially offset the penalty).
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: prefer reusing existing bins more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // Slight penalty per extra open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Discourage leaving residuals in the awkward 1..10 dead-zone range.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
