    if post_residual > 0 && next_item_size > 0 {
        let strand = (post_residual as f64 / cap) * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        if post_residual < next_item_size {
            score += 18.0 * strand;
        } else {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 14.0;
            } else if slack > 45 {
                score += 6.0;
            }
        }
    }

    // Scarcity-aware consolidation — sharpen preference for the tightest bin.
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / cap);
    }

    // Residual-band matching: reward post-residuals in the reusable band.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * progress;
        if (slack as f64) <= band {
            score -= 6.0 * (1.0 + 0.5 * progress);
        } else {
            score += (0.06 + 0.04 * (1.0 - progress)) * ((slack as f64) - band);
        }
    }

    // Variance-aware tightness: homogenize dispersed residuals.
    if mean_residual > 30.0 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }

    // Capacity-scaled waste anticipation.
    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
            }
        }
    }

    // Exact-sweep reward: clean bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Fleet-fit conservation — protect roomy residuals for large next items.
    if next_item_size > 0 && next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — when the next item plus a known small follow-up
    // would exactly retire the bin, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 31): two-step dead-space forecast.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        let pool = (mean_residual * open_bins_count as f64).max(1.0);
        let harvestable = (after as f64 / pool).min(1.0);
        if after < 5 && after > 0 {
            score += 2.0 * (1.0 - after as f64 / 5.0) * (1.0 - harvestable);
        }
        if after >= 11 && after as f64 <= mean_residual * 1.5 {
            score -= 3.0 * (1.0 - progress) * harvestable;
        }
    }

    // MUTATION (gen 31): global waste-pressure rebalance on the new-bin gate.
    if bin_residual == bin_capacity {
        let fleet_residual = mean_residual * open_bins_count as f64;
        let demand_proxy = next_item_size as f64 + 0.5 * mean_residual;
        if fleet_residual > demand_proxy * 1.2 {
            score += 6.0 * ((fleet_residual / demand_proxy) - 1.2).min(2.0);
        }
    }

    // MUTATION (gen 37): dead-space ratio compaction — directly penalize bins
    // whose post-residual fraction of capacity is stranded (unusable by the
    // next item) while rewarding bins that keep their waste ratio minimal.
    if next_item_size > 0 && post_residual > 0 && bin_residual < bin_capacity {
        let waste_frac = post_residual as f64 / cap;
        if post_residual < next_item_size {
            // Stranded space: penalize proportionally to waste fraction,
            // softened when the fleet is sparse (few bins to consolidate into).
            let fleet_sparse = (open_bins_count as f64).max(1.0) < 4.0;
            let weight = if fleet_sparse { 6.0 } else { 12.0 };
            score += weight * waste_frac * (1.0 - 0.5 * progress);
        } else {
            // Usable slack: reward keeping the waste ratio low relative to
            // what the next item will consume.
            let consumed_frac = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * consumed_frac * waste_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 37): residual-variance compaction trigger — when the
    // observed residual dispersion is high, add a mild extra pull toward the
    // bin whose post-residual lands closest to the fleet mean, homogenizing
    // leftovers so future mid-size items fit anywhere.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && open_bins_count >= 3 {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 15.0 {
            score -= 1.5 * (1.0 - dist / 15.0) * (mean_residual / cap).max(0.1);
        }
    }

    // MUTATION (gen 37): tightened new-bin gate under high fleet slack —
    // strengthen the existing waste-pressure rebalance with a progressive
    // term that scales with how much of the fleet residual is reusable by
    // the next item, discouraging redundant bin openings.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fleet_residual = mean_residual * open_bins_count as f64;
        let reusable = fleet_residual.min(next_item_size as f64 * 2.0);
        if fleet_residual > next_item_size as f64 {
            score += 4.0 * (reusable / (next_item_size as f64).max(1.0)) * (1.0 - progress);
        }
        // Late-stream compaction: with few items left, strongly prefer
        // squeezing into existing bins over opening fresh capacity.
        if progress > 0.85 {
            score += 14.0 * (progress - 0.85) / 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        score += 0.15 * (pr * pr) / bin_capacity as f64;
    }

    // Penalize dead space relative to typical future item sizes (10..80 => mid ~45).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 + 0.3 * slack_after_next as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if this bin becomes a trap.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: mildly penalize this one to preserve diversity.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Open a new bin when existing residuals are fragmented and few bins fit.
        let open_bonus = if fitting_bins_count == 0 { 0.0 } else {
            20.0 * (1.0 - pressure) + 30.0 * progress
        };
        score = 150.0 - open_bonus + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin has room for lookahead
        }
    }

    // Global state: many open bins with high mean residual => prefer consolidation.
    if open_bins_count > 0 && bin_residual < bin_capacity {
        let gap = mean_residual - bin_residual as f64;
        score += 0.05 * gap;
    }

    // Time horizon: early in stream, slightly prefer keeping residuals large/flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
