        } else {
            // Post residual too small for next item: mild penalty scaled by wasted space.
            score += 10.0 * (nx - post) / cap;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage consolidation.
    let bin_pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 2.0 * post_norm * bin_pressure;

    // Smooth consolidation term toward mean residual.
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
