    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
        let stranded = (next_item_size - post_residual) as f64;
        let rel = stranded / (item_size as f64).max(1.0);
        if rel > 0.5 {
            score += 5.0 * (rel - 0.5).min(1.0) * (1.0 - 0.5 * progress);
