    // a leftover of 1..=9 is essentially dead weight.
    if post_residual >= 1 && post_residual <= 9 {
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chain placements, scaled by how snugly next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 - snug * 0.3;
        } else {
            // Next item won't fit here: mild penalty, worse if leftover is
            // in an awkward harmonic class (class 0 or 1 => small leftover).
