    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is horrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: baseline anchor so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.15;
    }

    // Prefer filling bins when many bins are open (reduce fragmentation).
    score += (open_bins_count as f64) * 0.5;

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    // Mean-residual coupling: when average leftover is large, be pickier
    // about creating more small leftovers.
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 6.0;
    }

    score
}

