            score += 8.0 * dead / 100.0;
            if dead > 3.0 && dead < 18.0 {
                let collective = mean_residual * (open_bins_count as f64).max(1.0);
                if collective > next_item_size as f64 {
                    score += 2.0 + 0.2 * dead * (1.0 - progress);
                }
            }
        }
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next > 0 && after_next <= 12 {
            score -= 12.0;
        }
    }

    // Perfect closure bonus: bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 40.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Residual-deviation coupling: favor bins tighter than mean.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;
    if dev > 20.0 {
        score -= 6.0;
    }

    // Last-chance bin: strong preference to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure: fuller bins preferred, scaled with fleet size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 10.0;

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // Progress-scaled selectivity: early picky, late greedy.
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64) + (fitting_bins_count as f64) * 2.0;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
