        }
        if item_size <= 10 && open_bins_count > 0 {
            score += 40.0;
        }
        if fitting_bins_count > 2 {
            score += 5.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Fresh-bin lookahead: open only if leftover can chain the next item.
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if item_size >= 20 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // Global waste-pressure: force deeper packing when fleet residual is ample.
        let fleet_residual = mean_residual * open_bins_count as f64;
        let demand_proxy = next_item_size as f64 + 0.5 * mean_residual;
        if fleet_residual > demand_proxy * 1.2 {
            score += 6.0 * ((fleet_residual / demand_proxy) - 1.2).min(2.0);
        }
        // Waste anticipation for fresh bin.
        if next_item_size > 0 {
            let leftover = post_residual as i64 - next_item_size as i64;
            if leftover == 0 {
                score -= 9.0;
            } else if leftover < 0 {
                let stranded = (-leftover) as f64;
                if stranded < 8 {
                    score += 4.0 + 0.5 * stranded;
                } else {
                    score -= 2.0;
                }
            } else {
                let sliver = leftover as f64;
                if sliver < mean_residual {
                    score += 3.0 + 0.15 * sliver * (1.0 + progress);
                }
            }
        }
    }

    // MUTATION (gen 38): harvestability-weighted dead-space forecast —
    // penalize bins whose post-chain leftover is stranded relative to the
    // fleet's residual pool, reward mid-range harvestable leftovers.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        let pool = (mean_residual * open_bins_count as f64).max(1.0);
        let harvestable = (after as f64 / pool).min(1.0);
        if after > 0 && after < 5 {
            score += 2.0 * (1.0 - after as f64 / 5.0) * (1.0 - harvestable);
        }
        if after >= 11 && (after as f64) <= mean_residual * 1.5 {
            score -= 3.0 * (1.0 - progress) * harvestable;
        }
    }

    // MUTATION (gen 38): residual-band matching — steer toward post-residuals
    // in the reusable band just above the next item; excess slack is penalized
    // smoothly with a progress-softened gradient.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * progress;
        if slack <= band {
            score -= 6.0 * (1.0 + 0.5 * progress);
        } else {
            score += (0.06 + 0.04 * (1.0 - progress)) * (slack - band);
        }
    }

    // MUTATION (gen 38): variance-aware homogenization — when residuals are
    // dispersed, pull post-residuals toward the fleet mean to keep bins
    // interchangeable for future items.
    if mean_residual > 30.0 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let dist = (post_residual as f64 - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Near-perfect fit bonus: tiny post-residuals retire cleanly.
    if post_residual > 0 && post_residual <= 2 {
        score -= 20.0;
    }

    // Large-next-item conservation: protect roomy residuals early.
    if next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space more harshly when the gap becomes unusable
    // (too small for the smallest plausible item, or for the lookahead item).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(bin_capacity)) {
        score += 50.0;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // can't host the lookahead item
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 8.0;

    // Last chance: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure to keep the number of open bins low: penalize spreading
    // across many bins; mild bonus for filling an already-open bin.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with below-average residual (fill the emptiest useful bin),
    // which naturally pairs with best-fit behavior.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: discourage opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        // But if this item is huge and lookahead is large, opening fresh
        // space can be reasonable: soften the penalty.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight early-stream bias toward opening bins (exploration) vs late-stream
    // consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
