}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, compact fills (small post_residual) matter more.
    let progress_term = progress * progress * (1.0 - progress) * 4.0;
    score -= 8.0 * progress_term * (cap - post);

    // Penalize dead space quadratically when it cannot fit the next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size as f64 - post) / cap;
        score += 30.0 * gap * gap * (0.5 + progress);
    } else if next_item_size > 0 {
