        let fit_gap = (post - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - fit_gap).max(0.0) * (1.0 - progress);
    }

    // Tight-fit bonus (smooth, cubic in item fraction).
    let tight = item_norm * item_norm * item_norm;
    score -= 10.0 * tight;

