    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation).
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - post_norm).abs();

