            score -= 20.0;
        }
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
        if progress > 0.6 && mean_residual < 25.0 {
            score -= 8.0 * progress;
        }
        let fill = item_size as f64 / cap;
        if fill > 0.8 {
            score -= 18.0 * (fill - 0.8) * 5.0;
        }
        if item_size <= 10 && open_bins_count > 0 {
            score += 40.0;
        }
        if fitting_bins_count > 2 {
            score += 5.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Fresh-bin lookahead: only open if leftover can chain the next item.
        if next_item_size > 0 && post_residual > 0 {
            if post_residual < next_item_size && post_residual < 15 {
                score += 25.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            }
        }
        if item_size >= 20 && mean_residual >= item_size as f64 {
            score += 15.0;
        }
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // Waste-anticipation for the fresh-bin candidate.
        if next_item_size > 0 {
            let pr = post_residual as i64;
            let ni = next_item_size as i64;
            let leftover = pr - ni;
            if leftover == 0 {
                score -= 9.0;
            } else if leftover < 0 {
                let stranded = (-leftover) as f64;
                if stranded < 8 {
                    score += 4.0 + 0.5 * stranded;
                } else {
                    score -= 2.0;
                }
            } else {
                let sliver = leftover as f64;
                if sliver < mean_residual {
                    score += 3.0 + 0.15 * sliver * (1.0 + progress);
                }
            }
        }
        if mean_residual * (open_bins_count as f64) >= next_item_size as f64 && item_size < next_item_size {
            score += 8.0;
        }
        // MUTATION (gen 40): global waste-pressure rebalance — when total open
        // residual already exceeds remaining demand trend, tighten the new-bin
        // gate to force deeper packing into existing bins.
        let fleet_residual = mean_residual * open_bins_count as f64;
        let demand_proxy = next_item_size as f64 + 0.5 * mean_residual;
        if fleet_residual > demand_proxy * 1.2 {
            score += 6.0 * ((fleet_residual / demand_proxy) - 1.2).min(2.0);
        }
        // MUTATION (gen 40): exact-retirement gate — if opening a fresh bin
        // would leave exactly the next item's size of slack, that's fine, but
        // if the item nearly fills the fresh bin outright, prefer it.
        if next_item_size > 0 && item_size as f64 >= 0.9 * cap {
            score -= 25.0;
        }
    }

    // Dual-fit shaping: prefer bins whose post-residual is closest to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * ((next_item_size - post_residual) as f64 / cap) * (fitting_bins_count as f64);
    }

    // Near-exact fit bonus.
    if post_residual > 0 && post_residual <= 2 {
        score -= 20.0;
    }

    // Dead-space ratio shaping — steer toward dual/triple fits.
    if post_residual > 0 && next_item_size > 0 {
        let strand = (post_residual as f64 / cap) * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        if post_residual < next_item_size {
            score += 18.0 * strand;
        } else {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 14.0;
            } else if slack > 45 {
                score += 6.0;
            }
        }
    }

    // Scarcity-aware consolidation — sharpen preference for the tightest bin.
    if fitting_bins_count >= 3 && bin_residual < bin_capacity {
        score += 2.0 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / cap);
    }

    // Residual-band matching: reward post-residuals in the reusable band.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        let band = 6.0 + 0.25 * mean_residual + 4.0 * progress;
        if (slack as f64) <= band {
            score -= 6.0 * (1.0 + 0.5 * progress);
        } else {
            score += (0.06 + 0.04 * (1.0 - progress)) * ((slack as f64) - band);
        }
    }

    // Variance-aware tightness: homogenize dispersed residuals.
    if mean_residual > 30.0 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 6.0 * (1.0 - post_residual as f64 / mean_residual);
    }

    // Capacity-scaled waste anticipation.
    if fitting_bins_count >= 2 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        if dead > 3 && dead < 18 {
            let collective = mean_residual * (open_bins_count as f64).max(1.0);
            if collective > next_item_size as f64 {
                score += 2.0 + 0.2 * (dead as f64) * (1.0 - progress);
            }
        }
    }

    // Exact-sweep reward: clean bin retirement.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 8.0 + 0.5 * (open_bins_count as f64).min(20.0) + 6.0 * progress;
    }

    // Fleet-fit conservation — protect roomy residuals for large next items.
    if next_item_size > 0 && next_item_size > 40 && fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let room = post_residual as f64;
        if room >= next_item_size as f64 {
            score -= 4.0 * (1.0 - progress) * (room / cap);
        } else if room >= 0.7 * next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Adaptive scarcity gate on the dead-space penalty.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0 * (1.0 - progress);
    }

    // Continuous dead-space gradient — smooth waste curve on slack.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack > 3.0 {
            let usable_pool = (mean_residual * open_bins_count as f64).max(1.0);
            let absorbable = (slack / usable_pool.sqrt()).min(1.0);
            score += 0.10 * (slack - 3.0).min(60.0) * absorbable * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Near-perfect chain sharpening — leftover sliver 1..=4 retires cleanly.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 4 {
            score -= (3.0 + 2.0 * (4 - after) as f64) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // Residual homogenization pull — target post-residual near mean.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let pr = post_residual as f64;
        let dist = (pr - mean_residual).abs();
        if dist < 8.0 {
            score -= 2.5 * (1.0 - dist / 8.0) * (1.0 - progress);
        }
    }

    // Pair-fit anticipation — when the next item plus a small follow-up would
    // exactly retire the bin, reward strongly.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        if after >= 5 && after <= 10 {
            score -= 4.0 * (1.0 - after as f64 / 10.0) * (1.0 + progress);
        }
    }

    // Scarcity-weighted exact-fit gate.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score -= 6.0 * (2.0 - fitting_bins_count as f64) * (1.0 - post_residual as f64 / cap);
    }

    // MUTATION (gen 40, from best): two-step dead-space forecast — estimate
    // whether the residual left after placing the next item can still absorb a
    // fraction of the mean residual pool; strand small unusable slivers,
    // reward mid-range residuals that stay harvestable.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = post_residual - next_item_size;
        let pool = (mean_residual * open_bins_count as f64).max(1.0);
        let harvestable = (after as f64 / pool).min(1.0);
        if after < 5 && after > 0 {
            score += 2.0 * (1.0 - after as f64 / 5.0) * (1.0 - harvestable);
        }
        if after >= 11 && after as f64 <= mean_residual * 1.5 {
            score -= 3.0 * (1.0 - progress) * harvestable;
        }
    }

    // MUTATION (gen 40): fragmented-fleet gate — when many bins fit, penalize
    // creating a new unusable sliver; when few fit, tolerate it.
    if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
        let pressure = if fitting_bins_count >= 4 { 1.5 } else { 0.5 };
        score += pressure * (12 - post_residual) as f64 * (0.4 + 0.6 * (1.0 - progress));
    }

    // MUTATION (gen 40): mean-anchored slack matching — prefer post-residuals
    // within a narrow corridor around the fleet mean, scaled by scarcity.
    if post_residual >= next_item_size && next_item_size > 0 && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        let corridor = (mean_residual - slack).abs();
        if corridor < 5.0 {
            score -= 3.0 * (1.0 - corridor / 5.0) / (fitting_bins_count as f64).max(1.0).sqrt();
        }
    }

    // MUTATION (gen 40): tight-bin sweep priority — bins whose post-residual
    // is a tiny exact-chaining sliver get an extra scarcity-scaled bonus,
    // combining fine-grained residual fitting with lookahead anticipation.
    if post_residual > 0 && post_residual <= 6 && next_item_size > 0 && bin_residual < bin_capacity {
        let gap = (next_item_size as i64 - post_residual as i64).abs();
        if gap <= 3 {
            score -= 8.0 * (1.0 - gap as f64 / 3.0) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or closely fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 800.0; // two perfect placements in a row
        } else {
            score -= 300.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 50.0;
        if fitting_bins_count > 0 && post_residual == bin_capacity {
            score += 100.0;
        }
        // Late in stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly or closely fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 800.0; // two perfect placements in a row
        } else {
            // Scale lookahead reward by item rarity: if the next item is large
            // (hard to place), preserving room for it matters more.
            let large_next = next_item_size as f64 > 0.5 * bin_capacity as f64;
            let base = if large_next { 450.0 } else { 250.0 };
            score -= base * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally,
        // but only if the dead space is small enough that it's truly wasted.
        // Large leftover residuals may still fit future items drawn from the
        // stream, so temper the penalty by the mean residual of open bins.
        let dead = (next_item_size - post_residual) as f64;
        let wasted_frac = (dead / bin_capacity as f64).min(1.0);
        score += 0.5 * dead * (1.0 - 0.4 * (mean_residual / bin_capacity as f64).min(1.0)) * (0.5 + wasted_frac);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate logic: open a new bin only when the item would leave
    // an awkward residual in every existing bin AND the stream is still young
    // enough that future items can plausibly fill the fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Awkwardness of the best existing fit: how close post_residual is to
        // a "useless" sliver (small but nonzero).
        let awkward = if fitting_bins_count > 0 {
            // If placing here leaves a tiny unusable remainder, opening fresh
            // is attractive; if it leaves a huge residual, existing bins are fine.
            0.0
        } else {
            0.0
        };
        let _ = awkward;
        // Base cost of a new bin grows with stream progress: late in the
        // stream there is less time to fill a fresh bin, so prefer closing
        // out open bins instead.
        score += 40.0 + 120.0 * progress;
        // If the item is large relative to capacity, a fresh bin gives a
        // clean layout; reward slightly when next item is also large.
        if next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 30.0;
        }
        // Many open bins with slack: discourage yet another bin.
        if open_bins_count > 4 && mean_residual > 0.25 * bin_capacity as f64 {
            score += 60.0;
        }
    }

    // Compactness bonus: bins that are nearly full after placement are
    // valuable; give a graded reward proportional to fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if post_residual > 0 {
        score -= 20.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

