    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful (min item ~1)
    if post_residual > 0 && post_residual < 10 {
