    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; few open bins: encourage consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    // Prefer bins with residual below mean (fill emptier-relative space carefully)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late in stream: prefer exact consolidation, penalize waste more
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: neutral-ish baseline with mild penalty unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

