    // Tight-bin sweep priority — tiny exact-chaining slivers get a scarcity bonus.
    if post_residual > 0 && post_residual <= 6 && next_item_size > 0 && bin_residual < bin_capacity {
        let gap = (next_item_size as i64 - post_residual as i64).abs();
        if gap <= 3 {
            score -= 8.0 * (1.0 - gap as f64 / 3.0) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        }
    }

    // MUTATION (gen 41): near-exact chain band — reward residuals that leave
    // slack in 5..=15 after the next item, when the fleet mean suggests such
    // slivers get absorbed; combines lookahead with fine-grained fitting.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let after = (post_residual - next_item_size) as f64;
        if after > 10.0 && after <= 20.0 && mean_residual >= after * 0.5 {
            score -= 5.0 * (1.0 - (after - 10.0) / 10.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 41): late-stream consolidation surge — as the stream ends,
    // strongly prefer existing bins over opening new ones.
    if bin_residual == bin_capacity && progress > 0.5 {
        score += 25.0 * (progress - 0.5) * 2.0;
    }

    // MUTATION (gen 42): dead-space ratio coupling — combine fine-grained
    // residual fitting with lookahead anticipation. When placing the item
    // leaves a residual that is a poor fraction of the next item's size AND
    // the fleet has spare capacity to absorb the next item elsewhere, penalize
    // the stranded sliver proportionally; when the fleet cannot absorb it,
    // reward preserving room instead (avoid double-counting failure).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
        let dead = (next_item_size - post_residual) as f64;
        let dead_ratio = dead / next_item_size as f64;
        let fleet_pool = mean_residual * open_bins_count as f64;
        if fleet_pool >= next_item_size as f64 {
            score += 8.0 * dead_ratio * (1.0 - progress) * (1.0 + 1.0 / (fitting_bins_count as f64).max(1.0));
        } else {
            score -= 3.0 * (1.0 - dead_ratio) * (1.0 - progress);
        }
    }

    // MUTATION (gen 42): dual-granularity slack grading — split the slack
    // spectrum into fine (1..8), mid (9..25), coarse (26..) bands and apply
    // non-linear shaping: fine slack is great (bin retires soon), coarse
    // slack wastes capacity unless the mean residual says big gaps are normal.
    if next_item_size > 0 && post_residual > next_item_size && bin_residual < bin_capacity {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 8.0 {
            score -= 10.0 * (1.0 - slack / 8.0);
        } else if slack <= 25.0 {
            let mid_norm = (slack - 8.0) / 17.0;
            let fleet_norm = (mean_residual / cap).min(1.0);
            score += 4.0 * mid_norm * (1.0 - fleet_norm) - 2.0 * mid_norm * fleet_norm;
        } else {
            let excess = slack - 25.0;
            score += 0.15 * excess * (1.0 - (mean_residual / cap).min(1.0));
        }
    }

    // MUTATION (gen 42): new-bin gate refinement — when the fresh-bin leftover
    // would be a "dead zone" (too small for mean-typical items but nonzero),
    // apply a sharper penalty scaled by remaining stream length; conversely,
    // a fresh bin whose leftover exactly chains the next item earns a bonus.
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let dead_zone = post_residual < next_item_size && (next_item_size - post_residual) <= 10;
        if dead_zone {
            score += (4.0 + 0.3 * (next_item_size - post_residual) as f64) * (remaining / (total_items as f64).max(1.0)).min(1.0);
        }
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly or closely fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 800.0; // two perfect placements in a row
        } else {
            // Scale lookahead reward by item rarity: if the next item is large
            // (hard to place), preserving room for it matters more.
            let large_next = next_item_size as f64 > 0.5 * cap;
            let base = if large_next { 480.0 } else { 260.0 };
            // Sharpen reward for tight slack (near-exact two-item fits).
            let tightness = 1.0 - (slack as f64 / cap);
            score -= base * tightness * tightness;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally,
        // but only if the dead space is small enough that it's truly wasted.
        let dead = (next_item_size - post_residual) as f64;
        let wasted_frac = (dead / cap).min(1.0);
        let mean_frac = (mean_residual / cap).min(1.0);
        score += 0.55 * dead * (1.0 - 0.4 * mean_frac) * (0.5 + wasted_frac);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 220.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 120.0 * progress;

        // If the item is large relative to capacity, a fresh bin gives a
        // clean layout; reward slightly when next item is also large.
        if next_item_size as f64 > 0.5 * cap {
            score -= 30.0;
        }

        // Many open bins with slack: discourage yet another bin.
        if open_bins_count > 4 && mean_residual > 0.25 * cap {
            score += 60.0;
        }

        // Extra guard: late in the stream, opening a fresh bin wastes its
        // unused capacity almost surely — penalize harder as we near the end.
        if progress > 0.8 {
            score += 80.0 * (progress - 0.8) / 0.2;
        }
    }

    // Compactness bonus: graded reward for near-full bins, with a sharper
    // penalty for leaving small unusable slivers (residual 1..=3).
    let fill = (cap - post_residual as f64) / cap;
    if post_residual > 0 {
        score -= 20.0 * fill * fill;
        if post_residual <= 3 {
            // Tiny slivers are almost certainly dead space: penalize to steer
            // placements that fully close bins instead.
            score += 25.0 * (4 - post_residual) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
