        let dead = (next_item_size - post_residual) as f64;
        let wasted_frac = (dead / cap).min(1.0);
        // Penalize dead space harder when the stream is young (more items to come
        // that could have used that space) and mean residual is low (space is scarce).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (0.55 + 0.25 * (1.0 - progress)) * dead
            * (1.0 - 0.4 * (mean_residual / cap).min(1.0))
            * (0.5 + wasted_frac);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 220.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is most attractive early in the stream; late, prefer
        // squeezing into open bins.
        score += 40.0 + 140.0 * progress;
        // A fresh bin is attractive when the item is large and the next item is
        // also large: a clean layout avoids splitting awkward residuals.
        if next_item_size as f64 > 0.5 * cap {
            score -= 40.0;
        }
        // Many open bins with slack: discourage yet another bin.
        if open_bins_count > 4 && mean_residual > 0.25 * cap {
            score += 70.0;
        }
        // If item would leave a tiny unusable sliver in the best existing bin,
