    let fill = (bin_capacity - post_residual) as f64 / cap;
    if post_residual > 0 {
        score -= 22.0 * fill * fill * fill;
    }

    // Penalize residuals too small for typical future items: slivers are waste.
    if post_residual > 0 && (post_residual as f64) < 0.05 * cap {
        score += 15.0;
    }

    score
}

