pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly or closely fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 800.0; // two perfect placements in a row
        } else {
            // Scale lookahead reward by item rarity: if the next item is large
            // (hard to place), preserving room for it matters more.
            let large_next = next_item_size as f64 > 0.5 * bin_capacity as f64;
            let base = if large_next { 450.0 } else { 250.0 };
            score -= base * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally,
        // but only if the dead space is small enough that it's truly wasted.
        // Large leftover residuals may still fit future items drawn from the
        // stream, so temper the penalty by the mean residual of open bins.
        let dead = (next_item_size - post_residual) as f64;
        let wasted_frac = (dead / bin_capacity as f64).min(1.0);
        score += 0.5 * dead * (1.0 - 0.4 * (mean_residual / bin_capacity as f64).min(1.0)) * (0.5 + wasted_frac);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate logic: open a new bin only when the item would leave
    // an awkward residual in every existing bin AND the stream is still young
    // enough that future items can plausibly fill the fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
