        // would be to a "useless" sliver (small but nonzero). If placing the item
        // in an existing bin leaves a tiny remainder that likely can't host the
        // next item, opening a fresh bin is attractive; if it leaves a large
        // residual, existing bins are fine and we should keep them closed.
        let cap = bin_capacity as f64;
