            // Estimate the best existing post_residual from mean residual minus
            // the item: a proxy for what a typical existing bin would leave.
            let proxy_post = (mean_residual - item_size as f64).max(0.0);
            let sliver = if proxy_post > 0.0 && proxy_post < next {
                1.0 - proxy_post / next // small dead space => high awkwardness
            } else {
                0.0
            };
