        // stream there is less time to fill a fresh bin, so prefer closing
        // out open bins instead.
        score += 40.0 + 120.0 * progress;
        // Reward a fresh bin when existing placements would leave awkward
        // slivers (up to -50), making new-bin opening genuinely competitive.
        score -= 50.0 * awkward;
        // If the item is large relative to capacity, a fresh bin gives a
        // clean layout; reward slightly when next item is also large.
        if next_item_size as f64 > 0.5 * cap {
            score -= 30.0;
        }
        // Many open bins with slack: discourage yet another bin.
        if open_bins_count > 4 && mean_residual > 0.25 * cap {
            score += 60.0;
        }
    } else {
        // Existing-bin refinement: penalize residuals that are too small to
        // hold the next item but too large to ignore — "orphaned" space.
        // This pushes the heuristic toward placements that keep residuals
        // either zero or reusable, reducing dead space overall.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let orphan = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 35.0 * orphan * orphan;
        }
        // Reward residuals that can still hold typical stream items: a graded
        // bonus when post_residual >= next_item_size (complements the lookahead
        // term which focuses on near-exact fits).
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusability = post_residual as f64 / bin_capacity as f64;
            score -= 15.0 * reusability;
        }
    }

    // Compactness bonus: bins that are nearly full after placement are
    // valuable; give a graded reward proportional to fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if post_residual > 0 {
        score -= 20.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly or closely fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 850.0; // two perfect placements in a row
        } else {
            // Scale lookahead reward by item rarity: if the next item is large
            // (hard to place), preserving room for it matters more.
            let large_next = next_item_size as f64 > 0.5 * cap;
            let base = if large_next { 480.0 } else { 260.0 };
            // Sharper decay: only tight slack is worth much.
            let decay = (1.0 - slack as f64 / cap).powi(2);
            score -= base * decay;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally,
        // tempered by the mean residual of open bins (large leftovers may
        // still fit future items).
        let dead = (next_item_size - post_residual) as f64;
        let wasted_frac = (dead / cap).min(1.0);
        score += 0.55 * dead * (1.0 - 0.4 * (mean_residual / cap).min(1.0)) * (0.5 + wasted_frac);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 220.0;
    }

    // New-bin candidate logic: open a new bin only when the item would leave
    // an awkward residual in every existing bin AND the stream is still young
    // enough that future items can plausibly fill the fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Awkwardness of the best existing fit: a tiny nonzero remainder is
        // nearly unusable, a large remainder is still valuable space.
        let awkward = if fitting_bins_count > 0 {
            let best_post = post_residual; // this candidate is a new bin; approximate via mean
            let frac = (mean_residual / cap).min(1.0);
            // slivers (very small mean residual) are the worst outcome
            if frac > 0.0 && frac < 0.15 { 1.5 - frac * 6.0 } else { 0.0 }
        } else {
            0.0
        };
        let _ = (awkward, best_post_unused);
        // Base cost of a new bin grows with stream progress.
        score += 40.0 + 130.0 * progress;
        // If the item is large relative to capacity, a fresh bin gives a
        // clean layout; reward slightly when next item is also large.
        if next_item_size as f64 > 0.5 * cap {
            score -= 35.0;
        }
        // Many open bins with slack: discourage yet another bin.
        if open_bins_count > 4 && mean_residual > 0.25 * cap {
            score += 65.0;
        }
        // Late in the stream with few fitting bins, a fresh bin is wasteful.
        if progress > 0.8 && open_bins_count > 2 {
            score += 50.0;
        }
    }

    // Compactness bonus: bins that are nearly full after placement are
    // valuable; graded reward proportional to fill ratio squared.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if post_residual > 0 {
        score -= 22.0 * fill * fill;
    }

    score
}

