            // near-perfect chain fits are rewarded much more than loose ones.
            // Tighten further when the bin is one of few fitting options.
            let slack_frac = slack as f64 / cap;
            let scarcity = if fitting_bins_count <= 2 { 1.15 } else { 1.0 };
            score -= base * scarcity * (1.0 - slack_frac * slack_frac);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally,
        // tempered by mean residual (large residuals may still fit future items).
        // Extra weight when the dead space is a sliver too small for anything.
        let dead = (next_item_size - post_residual) as f64;
