    // Relative to mean residual: prefer bins tighter than average, with a
    // soft quadratic term so far-below-average residuals dominate ranking.
    let dev = mean_residual - post_residual as f64;
    score -= 0.32 * dev + 0.05 * dev * dev / cap;

