        // existing bin leaves a tiny unusable sliver, opening fresh is
        // attractive. Sliver threshold scales with the next item and with
        // the current item size (big items create big slivers).
        let sliver_thresh = ((next_item_size.max(item_size) as f64) * 0.5).min(0.15 * cap).max(3.0);
