            85.0 * (1.0 - post_residual as f64 / sliver_thresh)
        } else {
            0.0
        };
        score -= awkward;
        // Base cost of a new bin grows with stream progress.
        score += 40.0 + 130.0 * progress;
        // Large item + large next item: fresh bin gives a clean layout.
        if next_item_size as f64 > 0.5 * cap {
            score -= 40.0;
        }
        // Many open bins with slack: discourage yet another bin.
        if open_bins_count > 4 && mean_residual > 0.25 * cap {
            score += 70.0;
        }
        // Late in the stream with few fitting options: strongly avoid new bins.
        if progress > 0.7 && open_bins_count > 2 {
            score += 50.0 * progress;
        }
        // Early stream with a big item and no tight fits available: a fresh
        // bin keeps residuals large enough for future mid-size items.
        if progress < 0.3 && item_size as f64 > 0.6 * cap && fitting_bins_count > 0 && mean_residual < 0.2 * cap {
            score -= 30.0;
        }
    }

    // Compactness bonus: graded by fill ratio, extra kick near-full.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if post_residual > 0 {
        score -= 22.0 * fill * fill;
        if fill > 0.9 {
            score -= 18.0 * (fill - 0.9) / 0.1;
        }
    }

    score
}

