            let wasted_frac = (dead / cap).min(1.0);
            let scarcity = 1.0 + 0.25 / (fitting_bins_count.max(1) as f64);
            score += 0.55 * dead * (1.0 - 0.4 * (mean_residual / cap).min(1.0)) * (0.5 + wasted_frac) * scarcity;
        }
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 35.0;
        }
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next > 0 && after_next <= 12 {
            score -= 12.0;
        }
    }

    // Tightness reward: quadratic + cubic shaping on fill fraction after placement.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness - 20.0 * tightness * tightness * tightness;

    // Dead-space waste: penalize leftovers too small for typical items.
    if post_residual > 0 && post_residual < 20 && next_item_size != post_residual {
        let scarcity = 1.0 + 0.5 / (fitting_bins_count as f64).max(1.0);
        score += (25.0 + (20 - post_residual) as f64) * scarcity;
