                chain += 30.0 * (1.0 - slack_q / 0.06);
            }
            // NEW: multiplicative scarcity boost — when few bins can chain,
            // keeping a chainable residual is worth more.
            if fitting_bins_count <= 2 {
                chain *= 1.15;
            }
            score -= chain;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally,
        // tempered by mean residual (large residuals may still fit future items).
        let dead = (next_item_size - post_residual) as f64;
        let wasted_frac = (dead / cap).min(1.0);
        let scarcity = 1.0 + 0.3 / (fitting_bins_count.max(1) as f64);
        score += 0.6 * dead * (1.0 - 0.4 * (mean_residual / cap).min(1.0)) * (0.5 + wasted_frac) * scarcity;
    }

    // Relative to mean residual: prefer bins tighter than average, with a
    // soft quadratic term so far-below-average residuals dominate ranking.
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev + 0.06 * dev * dev / cap;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 240.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let sliver_thresh = ((next_item_size.max(item_size) as f64) * 0.5).min(0.15 * cap).max(3.0);
        let awkward = if fitting_bins_count > 0 && post_residual > 0 && (post_residual as f64) < sliver_thresh {
            90.0 * (1.0 - post_residual as f64 / sliver_thresh)
        } else {
            0.0
        };
