        score += 40.0 + 135.0 * progress;
        if next_item_size as f64 > 0.5 * cap {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.25 * cap {
            score += 70.0;
        }
        if progress > 0.7 && open_bins_count > 2 {
            score += 50.0 * progress;
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let best_chain = post_residual >= next_item_size;
            if !best_chain && next_item_size as f64 > 0.4 * cap {
                score -= 30.0;
            }
        }
        // When the incoming item nearly fills a fresh bin exactly
        // (item within 5% of capacity), a fresh bin wastes nothing — reward.
        let fill_new = item_size as f64 / cap;
        if fill_new > 0.95 {
