    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let x = r / c;
    let mut score = x * x * (1.0 + 2.0 * t) * c;

    // Perfect closure: dominant reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Exact chain fit: post residual exactly equals next item -> near-perfect
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 850.0;
    }

    // Polynomial coupling of post residual with stream progress
    let coupling = (x - 0.5) * (x - 0.5) * (1.0 + 3.0 * t * (1.0 - t) * 4.0);
    score += coupling * c * 0.5;

    // Chain lookahead: reward fits that leave room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let nr = next_item_size as f64;
        let slack_frac = slack / c;
        let base = if nr > 0.5 * c { 480.0 } else { 260.0 };
        let mut chain = base * (1.0 - slack_frac * slack_frac);
        if slack >= 0.5 * nr {
            chain += 60.0;
        }
        // Sweet spot: slack near a quarter of capacity
        let slack_q = (slack_frac - 0.25).abs();
        if slack_q < 0.05 {
            chain += 25.0;
        }
        if slack as u32 >= 2 * next_item_size {
            chain += 30.0;
        }
        score -= chain;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize wasted dead space
        let dead = (next_item_size - post_residual) as f64;
        let wasted_frac = (dead / c).min(1.0);
        let scarcity = 1.0 + 0.25 / (fitting_bins_count.max(1) as f64);
        score += 0.55 * dead * (1.0 - 0.4 * (mean_residual / c).min(1.0)) * (0.5 + wasted_frac) * scarcity;
    }

    // Reward last-chance bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 180.0 + 40.0 * t;
    }

    // Slight preference toward bins below mean residual
    let dev = mean_residual - r;
    score -= 0.3 * dev + 0.05 * dev * dev / c;

    // Late stream: discourage scattering
    score += t * open_bins_count as f64 * 0.3;

    // Compactness bonus graded by fill ratio
    let fill = (c - r) / c;
    if post_residual > 0 {
        score -= 20.0 * fill * fill;
        if fill > 0.9 {
            score -= 15.0 * (fill - 0.9) / 0.1;
        }
    }

    // Penalize unusable sliver residuals, scaled by remaining stream
    if post_residual > 0 && x < 0.1 {
        let stream_left = 1.0 - t;
        score += 12.0 * (1.0 - x / 0.1) * (0.5 + 0.5 * stream_left);
    }

    // New-bin candidate: penalize so it only wins when fits are terrible,
    // with graded relief for awkward slivers and large next items.
    if bin_residual == bin_capacity {
        let sliver_thresh = ((next_item_size.max(item_size) as f64) * 0.5).min(0.15 * c).max(3.0);
        let mut pen = 40.0 + 130.0 * t;
        if fitting_bins_count >= 2 && mean_residual > 0.3 * c {
            pen += 25.0;
        }
        if open_bins_count > 4 && mean_residual > 0.25 * c {
            pen += 40.0;
        }
        if t > 0.7 && open_bins_count > 2 {
            pen += 45.0 * t;
        }
        // If the next item is large and would not fit leftover space, ease penalty
        if next_item_size as f64 > 0.5 * c {
            pen -= 35.0;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && post_residual < next_item_size && next_item_size as f64 > 0.4 * c {
            pen -= 25.0;
        }
        // If the item would fit nearly perfectly in a fresh bin, ease the penalty
        let fill_new = item_size as f64 / c;
        if fill_new > 0.95 {
            pen -= 30.0 * (fill_new - 0.95) / 0.05;
        }
        score += pen;
    }

    score
}
